balanced:
import { numbers, recorder } from "./model";
import type { Node, Edge, Trace, Frame } from "./model";
export type Tree = {
    value: number;
    height: number;
    red?: boolean;
    left?: Tree;
    right?: Tree;
};
export function balanced(id: string, raw: string): Trace {
    const values = raw === "0"
        ? [30, 20, 10, 25, 40, 50, 5]
        : raw === "1"
            ? [30, 10, 20, 40, 50, 25]
            : numbers(raw);
    const avl = id === "avl", order = [...new Set(values)].sort((a, b) => a - b);
    const { frames, add } = recorder();
    let root: Tree | undefined, cursor = -1;
    const h = (p?: Tree): number => p?.height || 0;
    const update = (p: Tree) => {
        p.height = 1 + Math.max(h(p.left), h(p.right));
    };
    const refresh = (p?: Tree): void => {
        if (p) {
            refresh(p.left);
            refresh(p.right);
            update(p);
        }
    };
    const picture = () => {
        refresh(root);
        const nodes: Node[] = [], edges: Edge[] = [];
        const visit = (p: Tree | undefined, d: number, parent?: Tree) => {
            if (!p)
                return;
            nodes.push({
                id: String(p.value),
                label: String(p.value),
                x: 65 + (order.indexOf(p.value) * 550) / Math.max(1, order.length - 1),
                y: 45 + d * 88,
                color: avl
                    ? Math.abs(h(p.left) - h(p.right)) > 1
                        ? "orange"
                        : undefined
                    : p.red
                        ? "orange"
                        : undefined,
                subtitle: avl
                    ? `h=${h(p)} · BF=${h(p.left) - h(p.right)}`
                    : p.red
                        ? "Red node" : "Black node",
            });
            if (parent)
                edges.push({
                    from: String(parent.value),
                    to: String(p.value),
                    active: !avl && !!p.red,
                });
            visit(p.left, d + 1, p);
            visit(p.right, d + 1, p);
        };
        visit(root, 0);
        return { nodes, edges };
    };
    const snap = (title: string, detail: string, why: string, check: string, checkpoint = true, done = false) => {
        add(title, detail, {
            ...picture(),
            result: root,
            checkpoint,
            inputState: {
                source: values.map(String),
                current: cursor >= 0 && !done ? String(values[cursor]) : undefined,
                pending: values.slice(cursor + 1).map(String),
                processed: Math.max(0, cursor + (done ? 1 : 0)),
                label: "Insert in order; ignore duplicate keys",
            },
            explanation: {
                why,
                changes: detail,
                check,
                predict: done
                    ? "Predict the search path of the next input." : "Can rotations preserve the in-order sequence of every key?",
            },
        });
    };
    const rotate = (p: Tree, dir: "left" | "right") => {
        const q = dir === "left" ? p.right! : p.left!;
        if (dir === "left") {
            p.right = q.left;
            q.left = p;
        }
        else {
            p.left = q.right;
            q.right = p;
        }
        if (!avl) {
            q.red = p.red;
            p.red = true;
        }
        update(p);
        update(q);
        return q;
    };
    type Attach = (p: Tree) => void;
    const insert = (p: Tree | undefined, v: number, attach: Attach): Tree => {
        if (!p) {
            const node = { value: v, height: 1, red: !avl };
            attach(node);
            snap("Attach a new leaf", `${v} is attached to the complete tree; check upward along its search path.`, "BST ordering determines the insertion point; a new leaf may unbalance ancestors.", "Temporary imbalance is allowed; check all balance properties after repairs finish.", false);
            return node;
        }
        if (v === p.value) {
            snap("Ignore duplicate key", `${v} already exists; structure unchanged.`, "This lesson models a set without duplicate keys.", "Node count does not increase.", false);
            return p;
        }
        if (v < p.value)
            insert(p.left, v, (q) => {
                p!.left = q;
            });
        else
            insert(p.right, v, (q) => {
                p!.right = q;
            });
        update(p);
        const turn = (dir: "left" | "right", title: string, why: string) => {
            const old = p!.value, child = (dir === "left" ? p!.right : p!.left)!.value;
            snap("Before rotation:" + title, `Pivot ${old}; promote ${child}.`, why, "Compare in-order sequences before and after; keys must not disappear or change order.");
            p = rotate(p!, dir);
            attach(p);
            snap(title, `${child} becomes this subtree's root; ${old} moves down and the middle subtree is reattached.`, why, "The whole tree remains visible; the former ancestor now links to the new subtree root.");
        };
        if (avl) {
            const b = h(p.left) - h(p.right);
            if (b > 1) {
                if (h(p.left!.left) < h(p.left!.right)) {
                    const old = p.left!.value;
                    p.left = rotate(p.left!, "left");
                    snap("LR: rotate the left child left first", `Promote ${p.left.value}, move former left child ${old} down, then rotate ${p.value} right.`, "The left child's right side is taller; a single right rotation cannot repair this zigzag.", "This is a double rotation's intermediate state; full balance is not yet required.");
                }
                turn("right", "Rotate right to restore balance", `BF(${p.value})=${b}: left side taller; promote the tall side.`);
            }
            else if (b < -1) {
                if (h(p.right!.right) < h(p.right!.left)) {
                    const old = p.right!.value;
                    p.right = rotate(p.right!, "right");
                    snap("RL: rotate the right child right first", `Promote ${p.right.value}, move former right child ${old} down, then rotate ${p.value} left.`, "The right child's left side is taller; straighten the zigzag first.", "Intermediate state of a double rotation.");
                }
                turn("left", "Rotate left to restore balance", `BF(${p.value})=${b}: right side taller.`);
            }
        }
        else {
            if (p.right?.red && !p.left?.red)
                turn("left", "Rotate a red link left", "Left-leaning red\u2013black trees require red links on the left; rotate left for red-right/black-left.");
            if (p.left?.red && p.left.left?.red)
                turn("right", "Rotate consecutive red links right", "Two consecutive left red links represent a temporarily invalid 4-node shape.");
            if (p.left?.red && p.right?.red) {
                p.red = !p.red;
                p.left.red = false;
                p.right.red = false;
                snap("Flip colors", `Node ${p.value} merges the red link upward; both children become black.`, "Split a temporary 4-node; this may pass a conflict to the parent.", "The root becomes black at the end of insertion; it may be red temporarily.");
            }
        }
        update(p);
        attach(p);
        return p;
    };
    snap("Prepare insertion", values.join(" → "), "Predict the next key's search path, then observe repairs.", "An empty tree satisfies BST properties.", false);
    values.forEach((v, i) => {
        cursor = i;
        insert(root, v, (q) => {
            root = q;
        });
        if (!avl)
            root!.red = false;
        snap("Complete tree after insertion", `Insertion and repairs for ${v} complete.`, avl
            ? "Update heights from leaf to root, rotating only necessary ancestors." : "Coloring the root black completes this LLRB insertion repair.", avl
            ? "Every node has |BF|\u22641 and satisfies BST ordering." : "Black root, no consecutive red nodes, no right red links, equal black height on all root-to-null paths.", true, true);
    });
    return {
        frames,
        kind: "graph",
        result: root,
        caption: avl
            ? "Complete AVL tree; BF=left height\u2212right height, empty height 0. Orange marks temporary imbalance only." : "Complete LLRB insertion; orange=red node. Intermediate states may temporarily violate balance properties.",
    };
}

advanced:
import { recorder } from "./model";
import type { Frame, Node, Edge, Trace } from "./model";
export const advancedIds = [
    "treap",
    "splay",
    "lazy-segment",
    "persistent-segment",
    "sparse-table",
    "kd-tree",
];
export function advanced(id: string, raw: string): Trace {
    const variant = raw === "1", a = variant ? [8, 3, 7, 1, 6, 2, 5, 4] : [5, 2, 8, 1, 7, 3, 6, 4], { frames, add } = recorder();
    let kind: Trace["kind"] = "graph", result: unknown;
    let source = a.map(String);
    const note = (why: string, changes: string, check: string, predict = "Predict the next step, then verify it one step at a time.") => ({ why, changes, check, predict });
    const feed = (i: number): Frame["inputState"] => ({
        source,
        current: String(a[i]),
        pending: source.slice(i + 1),
        processed: i,
    });
    if (id === "treap" || id === "splay") {
        type T = {
            v: number;
            p: number;
            l?: T;
            r?: T;
        };
        let root: T | undefined;
        const priorities = variant
            ? [5, 80, 20, 60, 15, 70, 30, 90]
            : [70, 40, 90, 20, 60, 10, 80, 30];
        const picture = () => {
            const nodes: Node[] = [], edges: Edge[] = [];
            const go = (p: T | undefined, d: number, parent?: T) => {
                if (!p)
                    return;
                nodes.push({
                    id: String(p.v),
                    label: String(p.v),
                    x: 55 + (p.v - 1) * 80,
                    y: 45 + d * 80,
                    subtitle: id === "treap" ? `Priority ${p.p}` : undefined,
                });
                if (parent)
                    edges.push({ from: String(parent.v), to: String(p.v) });
                go(p.l, d + 1, p);
                go(p.r, d + 1, p);
            };
            go(root, 0);
            return { nodes, edges };
        };
        const attach = (parent: T | undefined, old: T, q: T) => {
            if (!parent)
                root = q;
            else if (parent.l === old)
                parent.l = q;
            else
                parent.r = q;
        };
        const rotate = (p: T, parent: T | undefined, left: boolean) => {
            const q = left ? p.r! : p.l!;
            if (left) {
                p.r = q.l;
                q.l = p;
            }
            else {
                p.l = q.r;
                q.r = p;
            }
            attach(parent, p, q);
            return q;
        };
        add("Empty tree", "Insert in initial order; node identities remain unchanged through rotations.", {
            ...picture(),
            inputState: { source, pending: source, processed: 0 },
        });
        a.forEach((v, i) => {
            const path: T[] = [];
            let p = root, parent: T | undefined;
            while (p) {
                path.push(p);
                parent = p;
                p = v < p.v ? p.l : p.r;
            }
            const n: T = { v, p: priorities[i] };
            if (!parent)
                root = n;
            else if (v < parent.v)
                parent.l = n;
            else
                parent.r = n;
            add("Attach a new leaf", `Insert ${v}${id === "treap" ? `, fixed teaching priority ${n.p}` : ""}.`, { ...picture(), inputState: feed(i) });
            if (id === "treap") {
                let child = n;
                while (path.length && path.at(-1)!.p > child.p) {
                    const old = path.pop()!, par = path.at(-1);
                    child = rotate(old, par, old.r === child);
                    add("Rotate to maintain priorities", `Promote ${child.v}: its priority ${child.p} is below its former parent ${old.v}'s priority ${old.p}.`, {
                        ...picture(),
                        inputState: feed(i),
                        checkpoint: true,
                        explanation: note("Insertion can violate heap order only along the parent chain; rotations preserve BST in-order order.", "Promote the lower-priority-number node and reconnect the middle subtree.", "All inserted nodes remain in the complete tree."),
                    });
                }
            }
        });
        if (id === "splay")
            for (const target of variant ? [1, 7, 3] : [4, 8, 2]) {
                const path: T[] = [];
                let p = root;
                while (p && p.v !== target) {
                    path.push(p);
                    p = target < p.v ? p.l : p.r;
                }
                while (p && path.length) {
                    const par = path.pop()!, g = path.pop(), gg = path.at(-1);
                    let title = "Zig: single rotation";
                    if (!g)
                        rotate(par, undefined, par.r === p);
                    else if ((g.l === par) === (par.l === p)) {
                        title = "Zig-zig: same-direction double rotation";
                        rotate(g, gg, g.r === par);
                        rotate(par, gg, par.r === p);
                    }
                    else {
                        title = "Zig-zag: opposite-direction double rotation";
                        rotate(par, g, par.r === p);
                        rotate(g, gg, g.r === p);
                    }
                    add(title, `Access ${target} and promote it along the path.`, {
                        ...picture(),
                        checkpoint: true,
                        explanation: note("Move the accessed node to the root to exploit repeated-access locality.", title, "Verify in-order traversal remains 1\u20268; a single operation may be linear."),
                    });
                }
                add("Access complete", `${target} is now the root.`, {
                    ...picture(),
                    checkpoint: true,
                });
            }
        result = root;
    }
    else if (id === "sparse-table") {
        kind = "matrix";
        const st: number[][] = [a.slice()];
        const pic = () => ({
            matrix: st.map((row) => a.map((_, i) => row[i] ?? "—")),
            rowLabels: st.map((_, k) => `2^${k}`),
            colLabels: a.map((_, i) => String(i)),
        });
        add("Length-1 intervals", a.join(", "), pic());
        for (let k = 1; 1 << k <= a.length; k++) {
            st[k] = [];
            for (let i = 0; i + (1 << k) <= a.length; i++) {
                st[k][i] = Math.min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
                add("Combine equal-length halves", `st[${k}][${i}]=min(${st[k - 1][i]},${st[k - 1][i + (1 << (k - 1))]})=${st[k][i]}。`, { ...pic(), cells: [[k, i]] });
            }
        }
        const l = variant ? 0 : 1, r = variant ? 6 : 5, k = Math.floor(Math.log2(r - l + 1)), value = Math.min(st[k][l], st[k][r - (1 << k) + 1]);
        result = { table: st, range: [l, r], value };
        add("Cover a query with two intervals", `min[${l},${r}]=min(${st[k][l]},${st[k][r - (1 << k) + 1]})=${value}。`, {
            ...pic(),
            cells: [
                [k, l],
                [k, r - (1 << k) + 1],
            ],
            checkpoint: true,
            explanation: note("min is idempotent, so overlapping intervals are valid.", `Cover [${l},${l + (1 << k) - 1}] and [${r - (1 << k) + 1},${r}].`, "Addition would double-count overlap; this query method would be invalid."),
        });
    }
    else if (id === "lazy-segment") {
        kind = "matrix";
        const sum = Array(4 * a.length).fill(0), tag = sum.slice(), ranges: Record<number, [
            number,
            number
        ]> = {};
        const build = (p: number, l: number, r: number) => {
            ranges[p] = [l, r];
            if (l === r) {
                sum[p] = a[l];
                return;
            }
            const m = (l + r) >> 1;
            build(p * 2, l, m);
            build(p * 2 + 1, m + 1, r);
            sum[p] = sum[p * 2] + sum[p * 2 + 1];
        };
        build(1, 0, a.length - 1);
        const pic = () => ({
            matrix: Object.keys(ranges).map((s) => {
                const p = +s;
                return [p, `[${ranges[p]}]`, sum[p], tag[p]];
            }),
            colLabels: ["Node", "Range", "sum", "lazy"],
        });
        add("Tree built", "sum stores the range sum; lazy starts at 0.", pic());
        const apply = (p: number, d: number) => {
            sum[p] += d * (ranges[p][1] - ranges[p][0] + 1);
            tag[p] += d;
        };
        const push = (p: number) => {
            if (tag[p]) {
                const d = tag[p];
                apply(p * 2, d);
                apply(p * 2 + 1, d);
                tag[p] = 0;
                add("Push down a lazy tag", `Pass node ${p}'s +${d} to both children and clear the parent's tag.`, {
                    ...pic(),
                    checkpoint: true,
                    explanation: note("Partial access requires children to reflect actual values.", "Add increment\u00D7length to each child's sum and accumulate its tag.", "Do not add to the parent's sum again; it already includes this increment."),
                });
            }
        };
        const update = (p: number, L: number, R: number, d: number) => {
            const [l, r] = ranges[p];
            if (R < l || r < L)
                return;
            if (L <= l && r <= R) {
                apply(p, d);
                add("Full coverage: defer expansion", `Add ${d} to all of [${l},${r}]: sum=${sum[p]}, lazy=${tag[p]}.`, { ...pic(), checkpoint: true });
                return;
            }
            push(p);
            update(p * 2, L, R, d);
            update(p * 2 + 1, L, R, d);
            sum[p] = sum[p * 2] + sum[p * 2 + 1];
            add("Merge upward", `Node ${p}'s range sum becomes the sum of its children: ${sum[p]}.`, pic());
        };
        const updates = variant
            ? [
                [0, 7, 2],
                [2, 5, 3],
            ]
            : [
                [0, 7, 3],
                [1, 4, 2],
            ];
        updates.forEach(([l, r, d]) => update(1, l, r, d));
        const query = (p: number, L: number, R: number): number => {
            const [l, r] = ranges[p];
            if (R < l || r < L) {
                add("Skip disjoint segments", `[${l},${r}] lies outside query [${L},${R}] and contributes 0.`, pic());
                return 0;
            }
            if (L <= l && r <= R) {
                add("Query fully covers this segment", `sum=${sum[p]} for [${l},${r}] already includes lazy tags; read it directly without visiting children.`, { ...pic(), checkpoint: true });
                return sum[p];
            }
            push(p);
            const value = query(p * 2, L, R) + query(p * 2 + 1, L, R);
            add("Combine both query contributions", `Node ${p} adds intersecting child results to obtain ${value}.`, pic());
            return value;
        };
        const value = query(1, 2, 6);
        result = { updates, range: [2, 6], value, total: sum[1] };
        add("Query complete", `The sum over [2,6] is ${value}.`, {
            ...pic(),
            checkpoint: true,
        });
    }
    else if (id === "persistent-segment") {
        type P = {
            id: string;
            l: number;
            r: number;
            sum: number;
            left?: P;
            right?: P;
        };
        let serial = 0;
        const roots: P[] = [];
        const build = (l: number, r: number): P => {
            const p: P = { id: `n${serial++}`, l, r, sum: 0 };
            if (l === r)
                p.sum = a[l];
            else {
                const m = (l + r) >> 1;
                p.left = build(l, m);
                p.right = build(m + 1, r);
                p.sum = p.left.sum + p.right.sum;
            }
            return p;
        };
        roots.push(build(0, a.length - 1));
        const pic = () => {
            const nodes: Node[] = [], edges: Edge[] = [], seen = new Set<string>();
            const walk = (p: P, d: number) => {
                if (seen.has(p.id))
                    return;
                seen.add(p.id);
                nodes.push({
                    id: p.id,
                    label: `${p.l}–${p.r}: ${p.sum}`,
                    x: 45 + ((p.l + p.r) / 2) * 80,
                    y: 80 + d * 80,
                });
                for (const c of [p.left, p.right])
                    if (c) {
                        edges.push({ from: p.id, to: c.id });
                        walk(c, d + 1);
                    }
            };
            // Show one version at a time; the table below reports shared node identities.
            walk(roots.at(-1)!, 0);
            return { nodes, edges };
        };
        add("Version 0", `Initial array ${a.join(", ")}; each node has a permanent ID.`, {
            ...pic(),
            stats: { "Version": 0, "Total nodes": serial },
        });
        const change = (p: P, at: number, value: number): P => {
            const q = { ...p, id: `n${serial++}` };
            add("Copy nodes along the visited path", `Set a[${at}]\u2190${value}; copy old node ${p.id} to ${q.id}, range [${p.l},${p.r}]. Old versions remain readable; the new root is not yet published.`, {
                ...pic(),
                worklists: [
                    {
                        name: "Nodes of the version being created",
                        items: [`${p.id} → ${q.id} [${p.l},${p.r}]`],
                    },
                ],
                checkpoint: true,
            });
            if (q.l === q.r)
                q.sum = value;
            else {
                if (at <= q.left!.r)
                    q.left = change(q.left!, at, value);
                else
                    q.right = change(q.right!, at, value);
                q.sum = q.left!.sum + q.right!.sum;
            }
            add("Fill copied nodes' range sums", `${q.id}'s new sum is ${q.sum}; old ${p.id} remains ${p.sum}. Unchanged children retain their old IDs.`, {
                ...pic(),
                tables: [
                    {
                        title: "Old nodes and new copies",
                        columns: ["Version", "ID", "sum"],
                        rows: [
                            ["Old", p.id, p.sum],
                            ["New", q.id, q.sum],
                        ],
                    },
                ],
            });
            return q;
        };
        const changes = variant
            ? [
                [2, 20],
                [6, 0],
            ]
            : [
                [1, 12],
                [5, 10],
            ];
        for (const [at, value] of changes) {
            const before = serial;
            roots.push(change(roots.at(-1)!, at, value));
            add("Path copy complete: new version ready", `a[${at}]\u2190${value}; created ${serial - before} nodes, with the old root unchanged.`, {
                ...pic(),
                checkpoint: true,
                stats: { "Version": roots.length - 1, "Total nodes": serial },
                explanation: note("Historical versions are immutable, so copy only the affected ancestor path.", `Old root ${roots[roots.length - 2].id}, new root ${roots.at(-1)!.id}.`, "Unvisited children keep the same node IDs; old range sums remain queryable."),
            });
        }
        const query = (p: P, l: number, r: number): number => r < p.l || p.r < l
            ? 0
            : l <= p.l && p.r <= r
                ? p.sum
                : query(p.left!, l, r) + query(p.right!, l, r);
        result = {
            roots,
            changes,
            queries: roots.map((p) => query(p, 1, 5)),
            nodeCount: serial,
        };
        add("Query historical versions side by side", "The same range [1,5] gives different historical answers from different roots.", {
            matrix: roots.map((p, i) => [i, p.id, p.sum, query(p, 1, 5)]),
            colLabels: ["Version", "Root ID", "Whole-range sum", "Sum [1,5]"],
            checkpoint: true,
        });
    }
    else if (id === "kd-tree") {
        type Point = [
            number,
            number
        ];
        type K = {
            point: Point;
            axis: number;
            id: string;
            left?: K;
            right?: K;
        };
        const points: Point[] = variant
            ? [
                [1, 8],
                [2, 2],
                [3, 6],
                [6, 1],
                [7, 7],
                [9, 4],
            ]
            : [
                [2, 3],
                [5, 4],
                [9, 6],
                [4, 7],
                [8, 1],
                [7, 2],
            ], q: Point = variant ? [6, 5] : [6, 3];
        let root: K | undefined;
        const nodes: Node[] = [], edges: Edge[] = [];
        const build = (ps: Point[], d: number, id: string, l: number, r: number, parent?: string): K | undefined => {
            if (!ps.length)
                return;
            const axis = d % 2, sorted = ps.slice().sort((a, b) => a[axis] - b[axis]), m = sorted.length >> 1, p: K = { point: sorted[m], axis, id };
            nodes.push({
                id,
                label: p.point.join(","),
                subtitle: `Split on ${axis ? "y" : "x"}`,
                x: (l + r) / 2,
                y: 45 + d * 95,
            });
            if (parent)
                edges.push({ from: parent, to: id });
            add("Median split", `Axis ${axis ? "y" : "x"}: choose (${p.point}), then recurse on left and right point sets.`, {
                nodes,
                edges,
                inputState: {
                    source: points.map(String),
                    current: String(p.point),
                    pending: [...sorted.slice(0, m), ...sorted.slice(m + 1)].map(String),
                    processed: points.length - ps.length,
                    label: "Pending shows points remaining in the current subproblem",
                },
                checkpoint: true,
            });
            p.left = build(sorted.slice(0, m), d + 1, id + "L", l, (l + r) / 2, id);
            p.right = build(sorted.slice(m + 1), d + 1, id + "R", (l + r) / 2, r, id);
            return p;
        };
        source = points.map(String);
        root = build(points, 0, "root", 10, 670);
        let best: K | undefined, bestD = Infinity;
        const dist = (p: Point) => (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2;
        const search = (p?: K) => {
            if (!p)
                return;
            const d = dist(p.point);
            if (d < bestD) {
                bestD = d;
                best = p;
            }
            add("Check nearest-neighbor candidate", `Query (${q}), node (${p.point}): distance\u00B2=${d}, current best=${bestD}.`, {
                nodes: nodes.map((n) => ({
                    ...n,
                    color: n.id === p.id ? "orange" : undefined,
                })),
                edges,
            });
            const delta = q[p.axis] - p.point[p.axis];
            search(delta < 0 ? p.left : p.right);
            if (delta * delta <= bestD) {
                add("Backtrack to the far side", `Split-plane distance\u00B2=${delta * delta} \u2264 best distance\u00B2=${bestD}; the far side may be closer.`, { nodes, edges, checkpoint: true });
                search(delta < 0 ? p.right : p.left);
            }
            else
                add("Prune the far side", `Plane distance\u00B2=${delta * delta} > ${bestD}; the far side cannot improve the result.`, { nodes, edges, checkpoint: true });
        };
        search(root);
        result = { points, query: q, nearest: best!.point, distanceSquared: bestD };
    }
    else
        throw Error("Unknown advanced structure");
    return {
        frames,
        kind,
        result,
        source,
        caption: "Reproducible mechanism lab; steps list specific inputs and parameters. Diagram space is not algorithmic auxiliary space.",
    };
}

