            checkpoint: true,
        });
    }
    else if (id === "decision-tree") {
        kind = "graph";
        const data = alt
            ? [
                [1, 0],
                [2, 1],
                [3, 1],
                [4, 0],
                [5, 0],
                [6, 1],
            ]
            : [
                [1, 0],
                [2, 0],
                [3, 1],
                [4, 1],
                [5, 0],
                [6, 0],
            ], nodes: Node[] = [], edges: Edge[] = [];
        source = data.map(([x, y]) => `x=${x} → ${y}`);
        type T = {
            threshold?: number;
            label?: number;
            left?: T;
            right?: T;
        };
        const gini = (rows: number[][]) => {
            if (!rows.length)
                return 0;
            const p = rows.filter((r) => r[1] === 1).length / rows.length;
            return 1 - p * p - (1 - p) * (1 - p);
        };
        const build = (rows: number[][], key: string, d: number, l: number, r: number, parent?: string): T => {
            const node: Node = {
                id: key,
                label: "Evaluating",
                x: (l + r) / 2,
                y: 45 + d * 85,
            };
            nodes.push(node);
            if (parent)
                edges.push({ from: parent, to: key });
            const ones = rows.filter((r) => r[1] === 1).length;
            if (!ones || ones === rows.length) {
                node.label = `Class ${ones ? 1 : 0}`;
                add("Pure leaf", `All ${rows.length} samples share one label; stop splitting.`, {
                    nodes,
                    edges,
                });
                return { label: ones ? 1 : 0 };
            }
            let best = Infinity, threshold = 0;
            for (let i = 0; i < rows.length - 1; i++) {
                const t = (rows[i][0] + rows[i + 1][0]) / 2, L = rows.filter((s) => s[0] <= t), R = rows.filter((s) => s[0] > t), score = (L.length * gini(L) + R.length * gini(R)) / rows.length;
                if (score < best) {
                    best = score;
                    threshold = t;
                }
                add("Compare candidate thresholds", `For x\u2264${t}, weighted Gini=${round(score)}; current best threshold ${threshold}.`, {
                    nodes,
                    edges,
                    stats: { "Current impurity": round(gini(rows)), "Candidate impurity": round(score) },
                });
            }
            node.label = `x ≤ ${threshold}`;
            add("Choose the best split", `Choose threshold ${threshold}; impurity falls from ${round(gini(rows))} to ${round(best)}.`, {
                nodes,
                edges,
                checkpoint: true,
                explanation: note("Minimize weighted impurity among this node's candidate thresholds.", "Left and right branches receive different subsets of training samples.", "Lower impurity describes only the training set; validation and pruning are still needed to limit overfitting."),
            });
