                threshold,
                left: build(rows.filter((s) => s[0] <= threshold), key + "L", d + 1, l, (l + r) / 2, key),
                right: build(rows.filter((s) => s[0] > threshold), key + "R", d + 1, (l + r) / 2, r, key),
            };
        };
        result = { tree: build(data, "root", 0, 0, 680), data };
    }
    else if (id === "minimax") {
        kind = "graph";
        const leaves = alt ? [8, 2, 5, 4, 1, 3, 7, 6] : [3, 5, 6, 9, 1, 2, 0, -1], nodes: Node[] = [], edges: Edge[] = [], pruned: number[] = [], visited: number[] = [];
        source = leaves.map(String);
        for (let i = 0; i < 15; i++) {
            const d = Math.floor(Math.log2(i + 1)), j = i - (2 ** d - 1);
            nodes.push({
                id: String(i),
                label: i >= 7 ? String(leaves[i - 7]) : d % 2 ? "MIN" : "MAX",
                x: ((j + 0.5) * 660) / 2 ** d + 10,
                y: 35 + d * 85,
            });
            if (i)
                edges.push({ from: String((i - 1) >> 1), to: String(i) });
        }
        add("Complete game tree", "Root MAX, next level MIN; leaves give utilities and both players act optimally.", {
            nodes,
            edges,
        });
        const mark = (i: number) => {
            pruned.push(i);
            nodes[i].color = undefined;
            nodes[i].subtitle = "Prune";
            if (i < 7) {
                mark(i * 2 + 1);
                mark(i * 2 + 2);
            }
        };
        const search = (i: number, alpha: number, beta: number, max: boolean): number => {
            visited.push(i);
            if (i >= 7) {
                add("Read leaf utility", `Node ${i} returns ${leaves[i - 7]}.`, {
                    nodes: nodes.map((n) => ({
                        ...n,
                        color: n.id === String(i) ? "orange" : n.color,
                    })),
                    edges,
                });
                return leaves[i - 7];
            }
            let value = max ? -Infinity : Infinity;
            for (const child of [i * 2 + 1, i * 2 + 2]) {
                const v = search(child, alpha, beta, !max);
                value = max ? Math.max(value, v) : Math.min(value, v);
                if (max)
                    alpha = Math.max(alpha, value);
                else
                    beta = Math.min(beta, value);
                nodes[i].label = `${max ? "MAX" : "MIN"} ${value}`;
                add("Update search bounds", `Node ${i}: \u03B1=${alpha}, \u03B2=${beta}, current value=${value}.`, { nodes, edges, checkpoint: true });
                if (alpha >= beta && child === i * 2 + 1) {
                    mark(i * 2 + 2);
                    add("Alpha\u2013beta pruning", `\u03B1=${alpha}\u2265\u03B2=${beta}: skip unvisited sibling subtrees.`, {
                        nodes,
                        edges,
                        checkpoint: true,
                        explanation: note("An ancestor already has an option at least as good; further search cannot change the root's optimal decision.", "Pruned nodes remain marked in the diagram; their utilities are not read.", "Pruning reduces computation without changing minimax results."),
                    });
                    break;
                }
            }
            return value;
        };
        const value = search(0, -Infinity, Infinity, true);
        result = { value, leaves, visited, pruned };
        add("Root decision", `Optimal root utility ${value}; visited ${visited.length}/15 nodes.`, { nodes, edges, checkpoint: true });
    }
    else
        throw Error("Unknown AI lesson");
    return {
        frames,
        kind,
        result,
        source,
        caption: "Small deterministic calculations demonstrate mechanisms and values, not a training platform or complete AI system. This lesson defines its inputs, stopping rules and implementation complexity.",
    };
}

