import { numbers, range, recorder } from "./model";
import type { Trace, Frame } from "./model";
export function sorting(id: string, raw: string, target = 5): Trace {
    const a = numbers(raw);
    let comparisons = 0, writes = 0;
    const { frames, add } = recorder(a);
    let worklists: Frame["worklists"];
    const emit = (title: string, detail: string, active: number[] = [], settled: number[] = [], pivot?: number) => add(title, detail, {
        values: a,
        active,
        settled,
        pivot,
        stats: { "Compare": comparisons, "Writes": writes },
        worklists,
    });
    const swap = (i: number, j: number) => {
        if (i !== j) {
            [a[i], a[j]] = [a[j], a[i]];
            writes += 2;
        }
    };
    emit("Prepare the experiment", `Input: ${a.length} elements. Green marks finalized values, orange the current pivot, purple active processing.`);
    if (id === "linear-search" || id === "binary-search") {
        if (!Number.isInteger(target) || target < 0 || target > 99)
            throw new Error("Search target must be an integer from 0 to 99.");
        if (id === "binary-search") {
            a.sort((a, b) => a - b);
            emit("Establish sorted input", "Sort the input automatically; this preprocessing is excluded from search comparison counts.");
        }
        let found = -1;
        if (id === "linear-search") {
            for (let i = 0; i < a.length; i++) {
                comparisons++;
                emit("Inspect one candidate", `a[${i}] = ${a[i]}; compare with target ${target}.`, [i]);
                if (a[i] === target) {
                    found = i;
                    break;
                }
            }
        }
        else {
            let lo = 0, hi = a.length - 1;
            while (lo <= hi) {
                const mid = Math.floor((lo + hi) / 2);
                comparisons++;
                emit("Inspect the interval midpoint", `Candidate interval [${lo}, ${hi}], mid=${mid}, value ${a[mid]}, target ${target}.`, [mid], range(a.length).filter((i) => i < lo || i > hi));
                if (a[mid] === target) {
                    found = mid;
                    break;
                }
                if (a[mid] < target)
                    lo = mid + 1;
                else
                    hi = mid - 1;
            }
        }
        emit(found < 0 ? "Target absent" : "Target found", found < 0 ? "The candidate interval is exhausted." : `One position of target ${target} is ${found}.`, [], found < 0 ? [] : [found]);
        return {
            frames,
            kind: "cells",
            result: found,
            caption: "Indices are zero-based; duplicates may return any matching position.",
        };
    }
    if (id === "bubble")
        for (let end = a.length - 1; end > 0; end--) {
            let changed = false;
            for (let j = 0; j < end; j++) {
                comparisons++;
                emit("Compare adjacent elements", `${a[j]} and ${a[j + 1]}: swap if inverted.`, [j, j + 1], range(a.length).filter((i) => i > end));
                if (a[j] > a[j + 1]) {
                    swap(j, j + 1);
                    changed = true;
                    emit("Swap an inversion", "Move the larger element one position right.", [j, j + 1]);
                }
            }
            if (!changed) {
                emit("Stop early", "A full pass made no swaps; the sequence is sorted.");
                break;
            }
        }
    else if (id === "selection")
        for (let i = 0; i < a.length - 1; i++) {
            let m = i;
            for (let j = i + 1; j < a.length; j++) {
                comparisons++;
                if (a[j] < a[m])
                    m = j;
                emit("Find the remaining minimum", `Current minimum candidate is at ${m}.`, [j, m], range(i));
            }
            swap(i, m);
            emit("Extend the sorted prefix", `Place the minimum at position ${i}.`, [i], range(i + 1));
        }
    else if (id === "insertion" || id === "shell") {
        const gaps = id === "shell"
            ? (() => {
                const g = [];
                for (let k = Math.floor(a.length / 2); k > 0; k = Math.floor(k / 2))
                    g.push(k);
                return g;
            })()
            : [1];
        for (const gap of gaps) {
            emit("Process a gap", `gap=${gap}; insertion-sort each gapped subsequence.`);
            for (let i = gap; i < a.length; i++) {
                const v = a[i];
                worklists = [
                    { name: "Held insertion value (logically removed from the array)", items: [String(v)] },
                ];
                let j = i;
                while (j >= gap) {
                    comparisons++;
                    emit("Compare the predecessor", `Insert ${v}; compare with position ${j - gap}.`, [
                        j,
                        j - gap,
                    ]);
                    if (a[j - gap] <= v)
                        break;
                    a[j] = a[j - gap];
                    writes++;
                    j -= gap;
                    emit("Shift backward", "Make room for the held value.", [j, j + gap]);
                }
                a[j] = v;
                worklists = undefined;
                writes++;
                emit("Insert at the target position", `Place ${v} at ${j}.`, [j]);
            }
        }
    }
    else if (id === "quick" || id === "quickselect") {
        const partition = (lo: number, hi: number) => {
            const p = a[hi];
            let i = lo;
            emit("Choose a pivot", `Last element ${p} of [${lo}, ${hi}] is the pivot.`, [], [], hi);
            for (let j = lo; j < hi; j++) {
                comparisons++;
                emit("Compare and partition", `${a[j]} ${a[j] <= p ? "≤" : ">"} ${p}; left boundary i=${i}.`, [j, i], [], hi);
                if (a[j] <= p) {
                    swap(i, j);
                    emit("Extend the left partition", "Include values no greater than the pivot in the left partition.", [i, j], [], hi);
                    i++;
                }
            }
            swap(i, hi);
            emit("Place the pivot", `The value at position ${i} is at its final rank.`, [], [i], i);
            return i;
        };
        if (id === "quick") {
            const go = (l: number, h: number) => {
                if (l >= h)
                    return;
                const p = partition(l, h);
                go(l, p - 1);
                go(p + 1, h);
            };
            go(0, a.length - 1);
        }
        else {
            const k = Math.floor((a.length - 1) / 2);
            let l = 0, h = a.length - 1;
            while (l <= h) {
                const p = partition(l, h);
                if (p === k)
                    break;
                if (p < k)
                    l = p + 1;
                else
                    h = p - 1;
            }
            emit("Select the k-th smallest", `The ${k + 1}-th smallest value is ${a[k]}; other values need not be fully sorted.`, [], [k]);
            return {
                frames,
                kind: "bars",
                result: a[k],
                caption: `Select rank k=${k + 1}; leave other parts unsorted to distinguish selection from sorting.`,
            };
        }
    }
    else if (id === "merge") {
        const go = (l: number, r: number) => {
            if (r - l < 2)
                return;
            const m = Math.floor((l + r) / 2);
            emit("Split the interval", `[${l}, ${r}) \u2192 [${l}, ${m}) and [${m}, ${r}).`, range(r - l).map((i) => i + l));
            go(l, m);
            go(m, r);
            const left = a.slice(l, m), right = a.slice(m, r);
            let i = 0, j = 0, k = l;
            while (i < left.length || j < right.length) {
                if (i < left.length && j < right.length)
                    comparisons++;
                a[k] =
                    j >= right.length || (i < left.length && left[i] <= right[j])
                        ? left[i++]
                        : right[j++];
                writes++;
                worklists = [
                    { name: "Left buffer \u00B7 not yet written back", items: left.slice(i).map(String) },
                    { name: "Right buffer \u00B7 not yet written back", items: right.slice(j).map(String) },
                ];
                emit("Merge two sorted segments", `Write position ${k}; take the left value first on equality to preserve stability.`, [
                    k,
                ]);
                k++;
            }
        };
        go(0, a.length);
    }
    else if (id === "heap-sort") {
        const sift = (i: number, n: number) => {
            while (2 * i + 1 < n) {
                let c = 2 * i + 1;
                if (c + 1 < n) {
                    comparisons++;
                    if (a[c + 1] > a[c])
                        c++;
                }
                comparisons++;
                if (a[i] >= a[c])
                    break;
                swap(i, c);
                emit("Repair the max-heap", `Swap parent ${i} with larger child ${c}.`, [i, c], range(a.length).filter((x) => x >= n));
                i = c;
            }
        };
        for (let i = Math.floor(a.length / 2) - 1; i >= 0; i--)
            sift(i, a.length);
        for (let end = a.length - 1; end > 0; end--) {
            swap(0, end);
            emit("Remove the maximum", `The maximum reaches final position ${end}.`, [0], range(a.length).filter((x) => x >= end));
            sift(0, end);
        }
    }
    else if (id === "counting") {
        const counts = Array(Math.max(...a) + 1).fill(0);
        for (let i = 0; i < a.length; i++) {
            counts[a[i]]++;
            worklists = [
                {
                    name: "Counting buckets \u00B7 value:frequency",
                    items: counts.flatMap((count, value) => count ? [`${value}:${count}`] : []),
                },
            ];
            emit("Count into a bucket", `count[${a[i]}] = ${counts[a[i]]}。`, [i]);
        }
        let k = 0;
        for (let v = 0; v < counts.length; v++)
            for (let j = 0; j < counts[v]; j++) {
                a[k] = v;
                writes++;
                emit("Reconstruct in bucket order", `Write item ${k} = ${v}.`, [k], range(k));
                k++;
            }
    }
    else if (id === "radix") {
        for (let exp = 1; Math.floor(Math.max(...a) / exp) > 0; exp *= 10) {
            const buckets: number[][] = Array.from({ length: 10 }, () => []);
            for (let i = 0; i < a.length; i++) {
                const d = Math.floor(a[i] / exp) % 10;
                buckets[d].push(a[i]);
                worklists = [
                    {
                        name: `Digit place ${exp} buckets \u00B7 preserve arrival order`,
                        items: buckets.flatMap((bucket, digit) => bucket.length ? [`${digit}: ${bucket.join(" → ")}`] : []),
                    },
                ];
                emit("Bucket by digit", `Value ${a[i]} has digit ${d} at place ${exp}.`, [i]);
            }
            a.splice(0, a.length, ...buckets.flat());
            writes += a.length;
            emit("Collect stably", `Finished digit place ${exp}; original order within each bucket is retained.`);
        }
    }
    else
        throw new Error(`Sorting lab not implemented: ${id}`);
    emit("Sorting complete", "All elements are in nondecreasing order.", [], range(a.length));
    return {
        frames,
        kind: "bars",
        result: [...a],
        caption: "Counts reflect comparisons and writes for this input, not a mathematical complexity proof.",
    };
}

