import { balanced } from "./balanced";
import { numbers, range, recorder } from "./model";
import type { Edge, Node, Trace, Frame } from "./model";
type Tree = {
    value: number;
    left?: Tree;
    right?: Tree;
    height: number;
    red?: boolean;
};
function treePicture(root: Tree | undefined) {
    const nodes: Node[] = [], edges: Edge[] = [];
    let index = 0;
    const go = (p: Tree | undefined, depth: number, parent?: string) => {
        if (!p)
            return;
        go(p.left, depth + 1, String(p.value));
        const id = String(p.value);
        nodes.push({
            id,
            label: id,
            x: 45 + index++ * 45,
            y: 35 + depth * 65,
            color: p.red ? "orange" : undefined,
        });
        if (parent)
            edges.push({ from: parent, to: id });
        go(p.right, depth + 1, id);
    };
    go(root, 0);
    const max = Math.max(1, index - 1);
    nodes.forEach((p) => (p.x = 50 + (((p.x - 45) / 45) * 580) / max));
    return { nodes, edges };
}
export function structures(id: string, raw: string): Trace {
    const { frames, add: record } = recorder();
    let inputState: Frame["inputState"];
    const feed = (source: (number | string)[], index: number) => {
        inputState = {
            source: source.map(String),
            current: String(source[index]),
            pending: source.slice(index + 1).map(String),
            processed: index,
        };
    };
    const add = (title: string, detail: string, extra: Partial<Frame> = {}) => record(title, detail, { inputState, ...extra });
    let result: unknown;
    let source: Trace["source"], output: Trace["output"];
    let kind: Trace["kind"] = "cells";
    if (id === "trie") {
        const words = raw.split(/[,，\s]+/).filter(Boolean);
        if (words.length < 2 ||
            words.length > 8 ||
            words.some((w) => !/^[a-zA-Z]{1,8}$/.test(w)))
            throw new Error("Enter 2\u20138 English words, each 1\u20138 characters.");
        const all = new Set<string>([""]), ends = new Set<string>();
        const picture = () => {
            const sorted = [...all].sort(), depths = new Map<number, string[]>();
            for (const s of sorted) {
                const row = depths.get(s.length) || [];
                row.push(s);
                depths.set(s.length, row);
            }
            const nodes = sorted.map((s) => ({
                id: s || "root",
                label: s === "" ? "root" : s.at(-1)! + (ends.has(s) ? " ✓" : ""),
                x: 35 +
                    ((depths.get(s.length)!.indexOf(s) + 1) * 610) /
                        (depths.get(s.length)!.length + 1),
                y: 25 + s.length * 37,
            }));
            const edges = sorted
                .filter(Boolean)
                .map((s) => ({ from: s.slice(0, -1) || "root", to: s }));
            return { nodes, edges };
        };
        add("Empty trie", "The root represents an empty prefix.", picture());
        for (const [inputIndex, word] of words.entries()) {
            feed(words, inputIndex);
            for (let i = 1; i <= word.length; i++) {
                const p = word.slice(0, i), exists = all.has(p);
                all.add(p);
                add(exists ? "Reuse a prefix" : "Create a character node", `Word ${word}, prefix ${p}: ${exists ? "already exists" : "add a new edge"}.`, picture());
            }
            ends.add(word);
            add("Mark a complete word", `\u2713 means ${word} is a whole word, not just a prefix.`, picture());
        }
        kind = "graph";
        result = [...ends];
    }
    else if (["avl", "red-black"].includes(id)) {
        return balanced(id, raw);
    }
    else if (id === "b-tree") {
        type B = {
            keys: number[];
            children: B[];
        };
        const root: B = { keys: [], children: [] };
        const input = raw === "1" ? [10, 20, 5, 6, 12, 30, 7, 17] : [1, 2, 3, 4, 5, 6, 7, 8, 9];
        const picture = () => {
            const nodes: Node[] = [], edges: Edge[] = [];
            const go = (p: B, l: number, r: number, d: number, key: string) => {
                nodes.push({
                    id: key,
                    label: p.keys.join(" · ") || "∅",
                    x: (l + r) / 2,
                    y: 40 + d * 95,
                });
                p.children.forEach((c, i) => {
                    const next = `${key}-${i}`, width = (r - l) / p.children.length;
                    edges.push({ from: key, to: next });
                    go(c, l + i * width, l + (i + 1) * width, d + 1, next);
                });
