                });
            }
            add("Implementation cost note", "An array records access order for visibility here, so movement is O(n). Expected O(1) LRU requires a hash table plus a doubly linked list.", { values: order });
            result = order;
        }
        else if (id === "bst") {
            let root: Tree | undefined;
            const insert = (p: Tree | undefined, v: number): Tree => {
                if (!p)
                    return { value: v, height: 1 };
                add("Compare the current BST node", `Compare ${v} with ${p.value}: ${v === p.value ? "Duplicate key: ignore" : v < p.value ? "Enter the left subtree" : "Enter the right subtree"}.`, treePicture(root));
                if (v < p.value)
                    p.left = insert(p.left, v);
                if (v > p.value)
                    p.right = insert(p.right, v);
                return p;
            };
            for (const [inputIndex, v] of a.entries()) {
                feed(a, inputIndex);
                root = insert(root, v);
                add("Descend by comparison", `Insert ${v}: smaller goes left, larger right; duplicates ignored.`, treePicture(root));
            }
            kind = "graph";
            result = root;
        }
        else if (id === "heap") {
            const h: number[] = [];
            const picture = () => ({
                nodes: h.map((v, i) => {
                    const d = Math.floor(Math.log2(i + 1)), j = i - (2 ** d - 1);
                    return {
                        id: String(i),
                        label: String(v),
                        x: ((j + 1) * 680) / (2 ** d + 1),
                        y: 35 + d * 70,
                    };
                }),
                edges: h.slice(1).map((_, i) => ({
                    from: String(Math.floor(i / 2)),
                    to: String(i + 1),
                })),
            });
            for (const [inputIndex, v] of a.entries()) {
                feed(a, inputIndex);
                h.push(v);
                add("Insert at the complete tree's end", `Append ${v}, then sift up through parents.`, picture());
                let i = h.length - 1;
                while (i > 0) {
                    const p = Math.floor((i - 1) / 2);
                    if (h[p] <= h[i])
                        break;
                    [h[p], h[i]] = [h[i], h[p]];
                    i = p;
                    add("Sift a smaller value upward", "Child is smaller than parent; swap and continue checking.", picture());
                }
            }
            kind = "graph";
            result = h;
            const built = [...h], minimum = h[0], last = h.pop()!;
            h[0] = last;
            add("Extract minimum and replace the root", `Remove ${minimum}; move last element ${last} to the root, preserving completeness, then restore heap order.`, picture());
            let at = 0;
            while (at * 2 + 1 < h.length) {
                let child = at * 2 + 1;
                if (child + 1 < h.length && h[child + 1] < h[child])
                    child++;
                add("Compare parent with the smaller child", `Compare ${h[at]} and ${h[child]}; continue only toward the smaller child.`, picture());
                if (h[at] <= h[child])
                    break;
                [h[at], h[child]] = [h[child], h[at]];
                at = child;
                add("Sift down to restore heap order", "After swapping, check the new parent\u2013child relationship.", picture());
            }
            add("Extraction complete", `Returned minimum ${minimum}; remaining parents are still no greater than their children.`, picture());
            output = {
                title: "Heap construction and extraction results",
                summary: [
                    `Built min-heap: ${built.join(", ")}`,
                    `Extracted minimum: ${minimum}`,
                    `Heap array after extraction: ${h.join(", ")}`,
                ],
            };
        }
        else if (id === "union-find") {
            const n = Math.min(a.length, 10), parent = range(n), size = Array(n).fill(1);
            const picture = () => ({
                nodes: parent.map((p, i) => ({
                    id: String(i),
                    label: `${i} → ${p}`,
                    x: 40 + (i * 600) / Math.max(1, n - 1),
                    y: p === i ? 75 : 200,
                })),
                edges: parent.flatMap((p, i) => p === i ? [] : [{ from: String(i), to: String(p), directed: true }]),
            });
            const find = (x: number): number => {
                if (parent[x] !== x)
                    parent[x] = find(parent[x]);
                return parent[x];
            };
            for (let i = 0; i < a.length - 1; i++) {
                feed(a, i);
                const u = a[i] % n, v = a[i + 1] % n;
                let x = find(u), y = find(v);
                if (x !== y) {
                    if (size[x] < size[y])
                        [x, y] = [y, x];
                    parent[y] = x;
                    size[x] += size[y];
                }
                add("Unite two sets", `union(${u}, ${v}); input values modulo ${n} become node IDs.`, picture());
            }
            for (let i = 0; i < n; i++) {
                find(i);
                add("Path compression", `find(${i}): visited nodes point directly to the representative.`, picture());
            }
            kind = "graph";
            result = parent;
        }
        else if (id === "fenwick") {
            const t = Array(a.length + 1).fill(0);
            for (let i = 0; i < a.length; i++)
                for (let j = i + 1; j < t.length; j += j & -j) {
                    feed(a, i);
                    t[j] += a[i];
                    add("Update ranges containing this point", `Add a[${i}]=${a[i]}: tree[${j}] += ${a[i]}; lowbit=${j & -j}.`, {
                        values: t.slice(1),
                        labels: range(a.length).map((x) => String(x + 1)),
                        active: [j - 1],
                    });
                }
            let sum = 0;
            for (let j = a.length; j > 0; j -= j & -j) {
                sum += t[j];
                add("Decompose a prefix query", `Add tree[${j}]=${t[j]}, running prefix sum ${sum}; remove the lowest set bit.`, { values: t.slice(1), active: [j - 1], stats: { "Prefix sum": sum } });
            }
            result = sum;
        }
        else if (id === "segment-tree") {
            const nodes: Node[] = [], edges: Edge[] = [];
            const intervals = new Map<string, {
                l: number;
                r: number;
                sum: number;
            }>();
            const build = (l: number, r: number, d: number, key: string, x1: number, x2: number): number => {
                const index = nodes.length;
                if (key !== "root")
                    edges.push({ from: key.slice(0, -1), to: key });
                nodes.push({
                    id: key,
                    label: `[${l},${r}]`,
                    x: (x1 + x2) / 2,
                    y: 30 + d * 65,
                });
                if (l === r) {
                    feed(a, l);
                    nodes[index].label = String(a[l]);
                    intervals.set(key, { l, r, sum: a[l] });
                    add("Leaves store point values", `Range [${l},${r}] = ${a[l]}.`, {
                        nodes,
                        edges,
                    });
                    return a[l];
                }
                const m = Math.floor((l + r) / 2), x = (x1 + x2) / 2;
                const sum = build(l, m, d + 1, key + "L", x1, x) +
                    build(m + 1, r, d + 1, key + "R", x, x2);
                nodes[index].label = `${l}–${r}: ${sum}`;
                intervals.set(key, { l, r, sum });
                inputState = {
                    source: a.map(String),
                    current: `Range [${l},${r}]`,
                    pending: a.slice(r + 1).map(String),
                    processed: r + 1,
                    label: "Merge constructed subranges",
                };
                add("Merge subranges", `sum[${l},${r}] = ${sum}。`, { nodes, edges });
                return sum;
            };
            result = build(0, a.length - 1, 0, "root", 5, 675);
            const L = 1, R = a.length - 1;
            const query = (key: string): number => {
                const { l, r, sum } = intervals.get(key)!;
                const disjoint = r < L || R < l, full = L <= l && r <= R;
                add(disjoint
                    ? "Skip a disjoint query range" : full
                    ? "Query fully covers this segment" : "Split the query into two subranges", `Query [${L},${R}], current range [${l},${r}]: ${disjoint ? "Return 0" : full ? `Read range sum ${sum} directly` : "Recurse into children and add both answers"}.`, {
                    nodes: nodes.map((n) => ({
                        ...n,
                        color: n.id === key ? "orange" : undefined,
                    })),
                    edges,
                    checkpoint: full,
                });
                return disjoint ? 0 : full ? sum : query(key + "L") + query(key + "R");
            };
            const answer = query("root");
            add("Range query complete", `Sum [${L},${R}] = ${answer}; neither the tree nor the original array was modified.`, { nodes, edges });
            output = {
                title: "Segment-tree query result",
                summary: [`Original array total: ${result}`, `Closed-range query [${L},${R}]: ${answer}`],
            };
            kind = "graph";
        }
        else
            throw new Error(`Unknown structure lab ${id}`);
    }
    if (inputState && frames.length)
        frames[frames.length - 1].inputState = {
            source: inputState.source,
            pending: [],
            processed: inputState.source.length,
            label: "Input processing complete",
        };
    return {
        frames,
        kind,
        result,
        source,
        output,
        caption: ["avl", "red-black", "b-tree", "skip-list"].includes(id)
            ? "Mechanism lab: switch curated inputs and observe maintenance rules step by step. Construction and maintenance show the complete structure." : "Operation lab: frames are independent snapshots, safe to step backward. Diagram layout differs from physical memory.",
    };
}

