import { recorder, range } from "./model";
import type { Edge, Node, Trace, Frame } from "./model";
export type Link = [
    number,
    number,
    number
];
export function graphScenario(id: string, variant: number): {
    links: Link[];
    directed: boolean;
} {
    const directed = !["graph", "bfs", "dfs", "kruskal", "prim"].includes(id);
    let links: Link[] = [
        [0, 1, 4],
        [0, 2, 2],
        [2, 1, 1],
        [1, 3, 5],
        [2, 3, 8],
        [2, 4, 10],
        [3, 4, 2],
        [3, 5, 6],
        [4, 5, 3],
    ];
    if (variant)
        links = [
            [0, 1, 7],
            [0, 2, 1],
            [2, 1, 2],
            [1, 3, 2],
            [2, 4, 9],
            [3, 4, 1],
            [4, 5, 2],
        ];
    if (id === "bellman-ford" && variant)
        links = [
            [0, 1, 4],
            [0, 2, 5],
            [1, 2, -2],
            [2, 3, 3],
            [3, 4, 1],
            [4, 5, 2],
        ];
    if (id === "scc")
        links = variant
            ? [
                [0, 1, 1],
                [1, 0, 1],
                [1, 2, 1],
                [2, 3, 1],
                [3, 2, 1],
                [3, 4, 1],
                [4, 5, 1],
            ]
            : [
                [0, 1, 1],
                [1, 2, 1],
                [2, 0, 1],
                [2, 3, 1],
                [3, 4, 1],
                [4, 3, 1],
                [4, 5, 1],
            ];
    if (id === "topological" && variant)
        links.push([5, 0, 1]);
    if (id === "max-flow")
        links = variant
            ? [
                [0, 1, 5],
                [0, 2, 3],
                [1, 3, 3],
                [2, 3, 4],
                [3, 5, 6],
                [1, 4, 2],
                [4, 5, 2],
            ]
            : [
                [0, 1, 8],
                [0, 2, 5],
                [1, 2, 3],
                [1, 3, 6],
                [2, 4, 7],
                [4, 3, 2],
                [3, 5, 7],
                [4, 5, 4],
            ];
    return { links, directed };
}
export function graphs(id: string, variant = 0): Trace {
    const { links, directed } = graphScenario(id, variant);
    const n = 6;
    const adj: Link[][] = Array.from({ length: n }, () => []);
    for (const [u, v, w] of links) {
        adj[u].push([u, v, w]);
        if (!directed)
            adj[v].push([v, u, w]);
    }
    const base: Node[] = range(n).map((i) => ({
        id: String(i),
        label: String.fromCharCode(65 + i),
        x: [65, 240, 240, 440, 440, 615][i],
        y: [160, 60, 255, 60, 255, 160][i],
    }));
    let reversed = false;
    let worklists: Frame["worklists"], residualGraph: number[][] | undefined;
    const edge = (path: Link[] = [], labels = false): Edge[] => (residualGraph
        ? residualGraph.flatMap((row, u) => row.flatMap((w, v) => (w > 0 ? [[u, v, w] as Link] : [])))
        : links).map(([u, v, w]) => ({
        from: String(reversed ? v : u),
        to: String(reversed ? u : v),
        label: labels || !["bfs", "dfs", "topological", "scc"].includes(id)
            ? String(w)
            : undefined,
        directed,
        active: path.some(([a, b]) => (a === u && b === v) || (!directed && a === v && b === u)),
    }));
    const { frames, add } = recorder();
    let result: unknown;
    let inputState: Frame["inputState"];
    const graphInput = links.map(([u, v, w]) => `${base[u].label}${directed ? "→" : "—"}${base[v].label} (${w})`);
    const emit = (title: string, detail: string, seen: number[] = [], current = -1, path: Link[] = [], dist?: number[]) => add(title, detail, {
        inputState,
        worklists,
        nodes: base.map((p, i) => ({
            ...p,
            label: p.label +
                (dist ? ` · ${Number.isFinite(dist[i]) ? dist[i] : "∞"}` : ""),
            color: i === current ? "orange" : seen.includes(i) ? "mint" : undefined,
        })),
        edges: [
            ...edge(path),
            ...(id === "max-flow" && !residualGraph
                ? path
                    .filter(([u, v]) => !links.some(([a, b]) => a === u && b === v))
                    .map(([u, v, w]) => ({
                    from: String(u),
                    to: String(v),
                    label: `Undo ${w}`,
                    directed: true,
                    active: true,
                }))
                : []),
        ],
        stats: {
            "Vertices": n,
            "Input edges": links.length,
            ...(residualGraph
                ? {
                    "Positive residual edges": residualGraph.reduce((sum, row) => sum + row.filter((w) => w > 0).length, 0),
                }
                : {}),
        },
    });
    emit("Read this diagram", `${directed ? "Arrows represent directed edges." : "Links are traversable in both directions."}Source A, target F. Switch scenarios to compare results.`);
    if (id === "graph") {
        for (let u = 0; u < n; u++)
            emit("Expand adjacency lists", `${base[u].label} \u2192 ${adj[u].map(([, v]) => base[v].label).join(", ") || "∅"}. Store only edges that exist.`, [], u, adj[u]);
        const m = range(n).map((u) => range(n).map((v) => (adj[u].some((e) => e[1] === v) ? 1 : 0)));
        add("Adjacency matrix of the same graph", "The matrix uses V\u00B2 space; 1 means an edge exists.", {
            matrix: m,
            rowLabels: base.map((x) => x.label),
            colLabels: base.map((x) => x.label),
            stats: { "List storage": `${n}+${links.length * 2}`, "Matrix cells": n * n },
        });
        result = m;
    }
    else if (id === "bfs" || id === "dfs") {
        const seen = new Set<number>([0]), frontier = [0], order: number[] = [];
        let head = 0;
        const frontierState = () => {
            const pending = (id === "bfs" ? frontier.slice(head) : [...frontier].reverse()).map((v) => base[v].label);
            worklists = [
                {
                    name: id === "bfs" ? "BFS queue \u00B7 front at left" : "DFS stack \u00B7 top at left",
                    items: pending,
                },
                { name: "Output visit order", items: order.map((v) => base[v].label) },
            ];
        };
        frontierState();
        emit("Initialize the pending container", "Mark start A on enqueue/push to avoid duplicate insertion.");
        while (frontier.length > head) {
            const u = id === "bfs" ? frontier[head++] : frontier.pop()!;
            order.push(u);
            frontierState();
            inputState = {
                source: graphInput,
                current: base[u].label,
                pending: (id === "bfs"
                    ? frontier.slice(head)
                    : [...frontier].reverse()).map((v) => base[v].label),
                processed: order.length,
                label: id === "bfs" ? "BFS queue (front at left)" : "DFS stack (next pop at left)",
            };
            emit(id === "bfs" ? "Dequeue the front" : "Expand the stack top", `Visit ${base[u].label}; pending: ${(id === "bfs" ? frontier.slice(head) : [...frontier].reverse()).map((v) => base[v].label).join(", ") || "Empty"}.`, order, u);
            for (const e of adj[u])
                if (!seen.has(e[1])) {
                    seen.add(e[1]);
                    frontier.push(e[1]);
                    frontierState();
                    inputState = {
                        ...inputState!,
                        pending: (id === "bfs"
                            ? frontier.slice(head)
                            : [...frontier].reverse()).map((v) => base[v].label),
                    };
                    emit("Discover a new vertex", `Discover ${base[e[1]].label} for the first time; add to ${id === "bfs" ? "Queue" : "Stack"}.`, order, e[1], [e]);
                }
        }
        result = order;
        emit("Traversal complete", `Visit order: ${order.map((v) => base[v].label).join(" → ")}.`, order);
    }
    else if (id === "dijkstra" || id === "astar") {
        const d = Array(n).fill(Infinity);
        d[0] = 0;
        const done: number[] = [], fixed = Array(n).fill(false);
        const predecessor = Array(n).fill(-1);
        const candidates = () => {
            worklists = [
                {
                    name: "Unsettled candidates \u00B7 linear scan, not a heap",
                    items: range(n)
                        .filter((v) => !fixed[v] && Number.isFinite(d[v]))
                        .sort((a, b) => d[a] - d[b])
                        .map((v) => `${base[v].label}: ${d[v]}`),
                },
                { name: "Settled", items: done.map((v) => base[v].label) },
            ];
        };
        candidates();
        emit("Initialize distances", "Only the start has distance 0; others are \u221E. Unreachable vertices are not yet finite candidates.", [], -1, [], d);
        while (done.length < n) {
            let u = -1;
            for (let i = 0; i < n; i++)
                if (!fixed[i] && (u < 0 || d[i] < d[u]))
                    u = i;
            if (u < 0 || !Number.isFinite(d[u]))
                break;
            done.push(u);
            fixed[u] = true;
            candidates();
            emit("Settle the minimum distance", `${base[u].label}'s distance ${d[u]} is settled. ${id === "astar" ? "This lab uses h=0, so f=g." : ""}`, done, u, [], d);
            for (const e of adj[u]) {
                const [, v, w] = e;
                if (d[u] + w < d[v]) {
                    d[v] = d[u] + w;
                    predecessor[v] = u;
                    candidates();
                    emit("Relax outgoing edges", `Reaching ${base[v].label} through ${base[u].label} is shorter; update to ${d[v]}.`, done, v, [e], d);
                }
            }
        }
        result = d;
        const route: Link[] = [];
        for (let v = 5; predecessor[v] >= 0; v = predecessor[v]) {
            const u = predecessor[v];
            route.unshift([u, v, adj[u].find((e) => e[1] === v)![2]]);
        }
        emit("Reconstruct the shortest path through predecessors", `Follow predecessors from F to A, then reverse: ${[0, ...route.map((e) => e[1])].map((v) => base[v].label).join(" → ")}.`, done, -1, route, d);
        emit("Shortest distance settled", `Minimum cost A \u2192 F: ${d[5]}.`, done, -1, route, d);
    }
    else if (id === "bellman-ford") {
        const d = Array(n).fill(Infinity);
        d[0] = 0;
        for (let k = 1; k < n; k++) {
            let changed = false;
            emit("Begin a relaxation round", `Round ${k}: scan every edge.`, [], -1, [], d);
            for (const e of links) {
                const [u, v, w] = e;
                if (Number.isFinite(d[u]) && d[u] + w < d[v]) {
                    d[v] = d[u] + w;
                    changed = true;
                    emit("Find a shorter path", `${base[u].label} \u2192 ${base[v].label}: new distance ${d[v]}.`, [], v, [e], d);
                }
            }
            if (!changed) {
                emit("Converged early", "No changes in a full round; stop.", [], -1, [], d);
                break;
            }
        }
        const negative = links.some(([u, v, w]) => Number.isFinite(d[u]) && d[u] + w < d[v]);
        result = { distances: d, negative };
        emit("Check for negative cycles", negative ? "A reachable negative cycle was detected." : "The extra check found no reachable negative cycle.", range(n), -1, [], d);
    }
    else if (id === "floyd") {
        const d = range(n).map((i) => range(n).map((j) => (i === j ? 0 : Infinity)));
        for (const [u, v, w] of links)
            d[u][v] = Math.min(d[u][v], w);
        const labels = base.map((x) => x.label);
        add("Initialize the distance matrix", "Diagonal entries are 0; unknown paths are \u221E.", {
            matrix: d.map((r) => r.map((x) => (Number.isFinite(x) ? x : "∞"))),
            rowLabels: labels,
            colLabels: labels,
        });
        for (let k = 0; k < n; k++)
            for (let i = 0; i < n; i++)
                for (let j = 0; j < n; j++)
                    if (d[i][k] + d[k][j] < d[i][j]) {
                        d[i][j] = d[i][k] + d[k][j];
                        add("Allow a new intermediate vertex", `Via ${labels[k]}, ${labels[i]} \u2192 ${labels[j]} shortens to ${d[i][j]}.`, {
                            matrix: d.map((r) => r.map((x) => (Number.isFinite(x) ? x : "∞"))),
                            rowLabels: labels,
                            colLabels: labels,
                            cells: [
                                [i, j],
                                [i, k],
                                [k, j],
                            ],
                            stats: { "Intermediate vertex": labels[k] },
                        });
                    }
        result = d;
        add("All pairs processed", "The matrix directly answers shortest-distance queries for any pair.", {
            matrix: d.map((r) => r.map((x) => (Number.isFinite(x) ? x : "∞"))),
            rowLabels: labels,
            colLabels: labels,
        });
    }
    else if (id === "topological") {
        const indeg = Array(n).fill(0);
        for (const [, v] of links)
            indeg[v]++;
        const q = range(n).filter((i) => !indeg[i]), order: number[] = [];
        let head = 0;
        const queueState = () => {
            worklists = [
                {
                    name: "Zero-indegree queue \u00B7 front at left",
                    items: q.slice(head).map((v) => base[v].label),
                },
                { name: "Output topological order", items: order.map((v) => base[v].label) },
            ];
        };
        queueState();
        emit("Compute indegrees", `Current zero-indegree vertices: ${q.map((i) => base[i].label).join(", ") || "None"}.`, [], -1, [], indeg);
        while (head < q.length) {
            const u = q[head++];
            order.push(u);
            queueState();
            emit("Dequeue a zero-indegree vertex", `Output ${base[u].label}; next remove its outgoing edges one by one.`, order, u, [], indeg);
            for (const e of adj[u]) {
                const v = e[1];
                indeg[v]--;
                if (indeg[v] === 0)
                    q.push(v);
                queueState();
                emit(indeg[v] === 0 ? "Indegree reaches zero: enqueue" : "Remove one dependency edge", `Processed ${base[u].label} \u2192 ${base[v].label}; ${base[v].label} now has indegree ${indeg[v]}. ${indeg[v] === 0 ? "It can safely join the queue's back." : "Other prerequisites remain; it cannot be enqueued."}`, order, v, [e], indeg);
            }
            emit("Remove a zero-indegree vertex", `Output ${base[u].label}; after removing its outgoing edges, queue: ${q
                .slice(head)
                .map((i) => base[i].label)
                .join(", ") || "Empty"}.`, order, u, adj[u], indeg);
        }
        result = { order, cycle: order.length < n };
        emit(order.length < n ? "Dependency cycle detected" : "Topological order complete", order.length < n
            ? "Remaining vertices have no zero-indegree entry point; not all tasks can be scheduled." : order.map((i) => base[i].label).join(" → "), order);
    }
    else if (id === "kruskal" || id === "prim") {
        const chosen: Link[] = [], parent = range(n), used = [0];
        const root = (x: number): number => parent[x] === x ? x : (parent[x] = root(parent[x]));
        if (id === "kruskal") {
            for (const e of [...links].sort((a, b) => a[2] - b[2])) {
                const [u, v, w] = e;
                if (root(u) !== root(v)) {
                    parent[root(u)] = root(v);
                    chosen.push(e);
                    emit("Connect two components", `${base[u].label} \u2014 ${base[v].label}, weight ${w}, creates no cycle.`, [], v, chosen);
                }
                else
                    emit("Skip a cycle-forming edge", `${base[u].label} and ${base[v].label} are already connected.`, [], -1, chosen);
            }
        }
        else {
            const inTree = new Set(used);
            while (used.length < n) {
                let e: Link | undefined;
                for (const candidate of links) {
                    const [u, v, w] = candidate;
                    if (inTree.has(u) !== inTree.has(v) && (!e || w < e[2]))
                        e = candidate;
                }
                if (!e)
                    break;
                const [u, v, w] = e;
                const next = inTree.has(u) ? v : u;
                used.push(next);
                inTree.add(next);
                chosen.push(e);
                emit("Choose the lightest cut edge", `Weight ${w}; the tree now has ${used.length} vertices.`, used, -1, chosen);
            }
        }
        const weight = chosen.reduce((s, e) => s + e[2], 0);
        result = { edges: chosen, weight };
        emit("Spanning tree complete", `Selected ${chosen.length} edges, total weight ${weight}.`, range(n), -1, chosen);
    }
    else if (id === "scc") {
        const seen = new Set<number>(), order: number[] = [];
        const stack: number[] = [];
        const stackState = () => {
            worklists = [
                {
                    name: "Recursive call stack \u00B7 top at left",
                    items: [...stack].reverse().map((v) => base[v].label),
                },
                {
                    name: reversed ? "Second-pass entry order" : "Finishing order \u00B7 append on exit only",
                    items: order.map((v) => base[v].label),
                },
            ];
        };
        const dfs = (u: number) => {
            seen.add(u);
            stack.push(u);
            stackState();
            emit("DFS the original graph", "Recurse into children, then record postorder on exit.", [...seen], u);
            for (const [, v] of adj[u])
                if (!seen.has(v))
                    dfs(v);
            order.push(u);
            stack.pop();
            stackState();
            emit("Return and record postorder", `All outgoing edges of ${base[u].label} are processed; append it to finishing order.`, [...seen], u);
        };
        for (let i = 0; i < n; i++)
            if (!seen.has(i))
                dfs(i);
        const rev: number[][] = range(n).map(() => []);
        for (const [u, v] of links)
            rev[v].push(u);
        seen.clear();
        reversed = true;
        order.reverse();
        stackState();
        emit("Reverse every directed edge", "The diagram now shows the transpose; search in reverse original finishing order.");
        const components: number[][] = [];
        const collect = (u: number, c: number[]) => {
            seen.add(u);
            c.push(u);
            stack.push(u);
            stackState();
            emit("Expand a component in the transpose", `Add ${base[u].label} to the current component and follow transposed arrows.`, c, u);
            for (const v of rev[u])
                if (!seen.has(v))
                    collect(v, c);
            stack.pop();
            stackState();
            emit("Return from transpose DFS", `All transpose neighbors of ${base[u].label} are processed; pop its call frame.`, c, u);
        };
        for (const u of order)
            if (!seen.has(u)) {
                const c: number[] = [];
                collect(u, c);
                components.push(c);
                emit("Extract one transpose component", `Current strongly connected component: ${c.map((i) => base[i].label).join(", ")}.`, c);
            }
        result = components;
        emit("Strongly connected components complete", components
            .map((c) => `{${c.map((i) => base[i].label).join(", ")}}`)
            .join(" / "));
    }
    else if (id === "max-flow") {
        const residual = range(n).map(() => Array(n).fill(0));
        for (const [u, v, w] of links)
            residual[u][v] += w;
        residualGraph = residual;
        const neighbors: number[][] = range(n).map((u) => [
            ...new Set(links.flatMap(([a, b]) => (a === u ? [b] : b === u ? [a] : []))),
        ]);
        let total = 0;
        while (true) {
            const parent = Array(n).fill(-1), q = [0];
            parent[0] = 0;
            let head = 0;
            const queueState = () => {
                worklists = [
                    {
                        name: "Residual BFS queue \u00B7 front at left",
                        items: q.slice(head).map((v) => base[v].label),
                    },
                    {
                        name: "Discovered this round",
                        items: range(n)
                            .filter((v) => parent[v] >= 0)
                            .map((v) => base[v].label),
                    },
                ];
            };
            queueState();
            emit("Search again for a residual augmenting path", "Clear visited and queue each round, restarting at A; edge labels show positive residual capacities.", [], 0);
            while (head < q.length && parent[5] < 0) {
                const u = q[head++];
                queueState();
                emit("Residual BFS dequeue", `Remove ${base[u].label}; expand only edges with positive residual capacity.`, q, u);
                for (const v of neighbors[u])
                    if (parent[v] < 0 && residual[u][v] > 0) {
                        parent[v] = u;
                        q.push(v);
                        queueState();
                        emit("Residual BFS discovers a vertex", `${base[u].label} \u2192 ${base[v].label} has residual ${residual[u][v]}; record predecessor and enqueue.`, q, v, [[u, v, residual[u][v]]]);
                    }
            }
            if (parent[5] < 0)
                break;
            let amount = Infinity;
            const path: Link[] = [];
            for (let v = 5; v !== 0; v = parent[v])
                amount = Math.min(amount, residual[parent[v]][v]);
            for (let v = 5; v !== 0; v = parent[v])
                path.unshift([parent[v], v, amount]);
            worklists = [
                ...(worklists || []),
                {
                    name: "Augmenting path \u00B7 source to sink",
                    items: ["A", ...path.map((e) => base[e[1]].label)],
                },
            ];
            emit("Find an augmenting path and bottleneck", `Minimum path residual: ${amount}. Next update forward and reverse residuals together.`, [], 5, path);
            for (let v = 5; v !== 0; v = parent[v]) {
                const u = parent[v];
                residual[u][v] -= amount;
                residual[v][u] += amount;
            }
            total += amount;
            emit("Increase flow along the augmenting path", `Bottleneck ${amount}, total flow ${total}; increase reverse residual capacity to permit cancellation.`, [], 5, path);
            add("Inspect the residual network", "Each cell is additional available flow; reverse cells record cancellable flow.", {
                worklists,
                matrix: residual,
                rowLabels: base.map((x) => x.label),
                colLabels: base.map((x) => x.label),
                stats: { "Total flow": total },
            });
        }
        result = total;
        emit("No augmenting path remains", `Final maximum flow = ${total}.`);
    }
    else
        throw new Error(`Unknown graph lab ${id}`);
    return {
        frames,
        kind: "graph",
        result,
        source: graphInput,
        caption: "Curated six-vertex scenarios; node labels can include distances/indegrees. Weights and paths are computed from scenario data.",
    };
}

strategies:
import { numbers, range, recorder, textPair } from "./model";
import type { Trace } from "./model";
export function strategies(id: string, raw: string): Trace {
    const { frames, add } = recorder();
    let result: unknown, kind: Trace["kind"] = "cells";
    let source: Trace["source"];
    if (id === "lcs" || id === "edit-distance") {
        const [a, b] = textPair(raw, 12), d = range(a.length + 1).map(() => Array(b.length + 1).fill(0));
        if (id === "edit-distance") {
            for (let i = 0; i <= a.length; i++)
                d[i][0] = i;
            for (let j = 0; j <= b.length; j++)
                d[0][j] = j;
        }
        const base = { rowLabels: ["∅", ...a], colLabels: ["∅", ...b] };
        add("Initialize empty prefixes", "The first row and column represent subproblems with one empty side.", {
            matrix: d,
            ...base,
        });
        for (let i = 1; i <= a.length; i++)
            for (let j = 1; j <= b.length; j++) {
                const same = a[i - 1] === b[j - 1];
                d[i][j] =
                    id === "lcs"
                        ? same
                            ? d[i - 1][j - 1] + 1
                            : Math.max(d[i - 1][j], d[i][j - 1])
                        : Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (same ? 0 : 1));
                add("Fill a prefix state", `${a[i - 1]} and ${b[j - 1]} are ${same ? "equal" : "different"}. dp[${i}][${j}] = ${d[i][j]}. ${id === "lcs" ? "On equality take diagonal +1; otherwise max(top,left)." : "Compare deletion, insertion and replacement."}`, {
                    matrix: d,
                    ...base,
                    cells: [[i, j]],
                    stats: { "Filled states": (i - 1) * b.length + j },
                });
            }
        result = d[a.length][b.length];
        add("Read the final answer", `${id === "lcs" ? "Longest common subsequence length" : "Minimum edit count"} = ${result}。`, { matrix: d, ...base, cells: [[a.length, b.length]] });
        kind = "matrix";
    }
    else if (id === "knapsack") {
        const items = raw === "1"
            ? [
                [1, 2],
                [3, 5],
                [4, 6],
                [5, 8],
            ]
            : [
                [2, 3],
                [3, 4],
                [4, 5],
                [5, 8],
            ], W = raw === "1" ? 8 : 7, d = range(items.length + 1).map(() => Array(W + 1).fill(0));
        source = [
            `Capacity W=${W}`,
            ...items.map(([w, v], i) => `Item ${i + 1}: weight ${w} / value ${v}`),
        ];
        const base = {
            rowLabels: ["No items", ...items.map(([w, v]) => `Weight ${w}/value ${v}`)],
            colLabels: range(W + 1).map(String),
        };
        add("Initialize knapsack", "Rows are available-item prefixes; columns are capacities. Each item can be selected at most once.", {
            matrix: d,
            ...base,
        });
        for (let i = 1; i <= items.length; i++)
            for (let c = 0; c <= W; c++) {
                const [w, v] = items[i - 1], skip = d[i - 1][c], take = c >= w ? d[i - 1][c - w] + v : -Infinity;
                d[i][c] = Math.max(skip, take);
                add("Compare taking and skipping", `Item ${i}, capacity ${c}: skip=${skip}, take=${Number.isFinite(take) ? take : "Does not fit"}, choose ${d[i][c]}.`, { matrix: d, ...base, cells: [[i, c]] });
            }
        let c = W;
        const picked: number[] = [];
        for (let i = items.length; i > 0; i--)
            if (d[i][c] !== d[i - 1][c]) {
                picked.push(i);
                c -= items[i - 1][0];
            }
        result = d[items.length][W];
        add("Backtrack the selection", `Optimal value ${result}; selected item IDs ${picked.reverse().join(", ")}.`, { matrix: d, ...base });
        kind = "matrix";
    }
    else if (id === "backtracking") {
        const n = 4, queens: number[] = [], solutions: number[][] = [];
        source = [
            "4\u00D74 board",
            "One queen per row",
            "Columns and both diagonals must not conflict",
            raw === "1" ? "Try columns right to left" : "Try columns left to right",
        ];
        const board = () => range(n).map((r) => range(n).map((c) => (queens[r] === c ? "♛" : "·")));
        add("Four-queens search", "One queen per row, with no column or diagonal conflicts.", {
            matrix: board(),
        });
        const go = (r: number) => {
            if (r === n) {
                solutions.push([...queens]);
                add("Found a complete solution", `Solution ${solutions.length}; continue backtracking for others.`, { matrix: board(), stats: { "Solutions": solutions.length } });
                return;
            }
            const cols = raw === "1" ? range(n).reverse() : range(n);
            for (const c of cols) {
                const ok = queens.every((q, i) => q !== c && Math.abs(q - c) !== r - i);
                if (!ok) {
                    add("Prune a conflict", `Row ${r + 1}, column ${c + 1} conflicts with an existing queen; abandon this branch.`, {
                        matrix: board(),
                        cells: [[r, c]],
                        stats: { "Solutions": solutions.length },
                    });
                    continue;
                }
                queens.push(c);
                add("Try a placement", `Place a queen at (${r + 1},${c + 1}).`, {
                    matrix: board(),
                    cells: [[r, c]],
                });
                go(r + 1);
                queens.pop();
                add("Undo the choice", "Return to the previous level and restore the pre-branch state.", {
                    matrix: board(),
                });
            }
        };
        go(0);
        queens.push(...solutions[0]);
        add("Search complete", `Found ${solutions.length} solutions; the first is displayed.`, {
            matrix: board(),
            stats: { "Solutions": solutions.length },
        });
        kind = "board";
        result = solutions;
    }
    else if (id === "greedy") {
        const intervals = raw === "1"
            ? [
                [0, 4],
                [1, 2],
                [2, 3],
                [3, 5],
                [4, 6],
            ]
            : [
                [0, 6],
                [1, 4],
                [3, 5],
                [5, 7],
                [5, 9],
                [8, 9],
            ];
        source = intervals.map(([l, r]) => `[${l},${r})`);
        intervals.sort((a, b) => a[1] - b[1]);
        let end = -Infinity;
        const chosen: number[][] = [];
        add("Sort by finish time", "Intervals are [start,end); touching endpoints are allowed.", {
            matrix: intervals,
            colLabels: ["Start", "End"],
        });
        intervals.forEach(([s, e], i) => {
            const ok = s >= end;
            if (ok) {
                chosen.push([s, e]);
                end = e;
            }
            add(ok ? "Accept activity" : "Skip conflicting activity", `[${s},${e}) ${ok ? "does not conflict: select it" : "conflicts with a selected activity"}; ${chosen.length} selected.`, {
                matrix: intervals,
                colLabels: ["Start", "End"],
                cells: [
                    [i, 0],
                    [i, 1],
                ],
                stats: { "Selected count": chosen.length },
            });
        });
        result = chosen;
        kind = "matrix";
    }
    else if (id === "fibonacci") {
        const n = numbers(raw, 1, 1, 20)[0];
        if (n < 2)
            throw new Error("Enter at least 2.");
        const cache: (number | undefined)[] = Array(n + 1).fill(undefined), stack: number[] = [];
        cache[0] = 0;
        cache[1] = 1;
        source = [`n=${n}`, "F(0)=0", "F(1)=1"];
        const snapshot = () => ({
            values: cache.map((x) => x ?? 0),
            labels: cache.map((x, i) => `${i}:${x ?? "?"}`),
            worklists: [
                {
                    name: "Recursive call stack \u00B7 top at left",
                    items: [...stack].reverse().map((k) => `F(${k})`),
                },
                {
                    name: "Cached subproblems",
                    items: cache.flatMap((v, i) => v === undefined ? [] : [`F(${i})=${v}`]),
                },
            ],
        });
        add("Prepare memoization cache", "Only F(0) and F(1) are known; question marks mean uncomputed.", snapshot());
        const fib = (k: number): number => {
            stack.push(k);
            add("Enter a recursive call", `Request F(${k}); check the cache first.`, snapshot());
            if (cache[k] !== undefined) {
                add("Cache hit: return directly", `F(${k})=${cache[k]} is already computed; no subtree expansion needed.`, { ...snapshot(), checkpoint: true });
            }
            else {
                const left = fib(k - 1), right = fib(k - 2);
                cache[k] = left + right;
                add("Combine and cache", `F(${k})=${left}+${right}=${cache[k]}; reuse this result later.`, { ...snapshot(), checkpoint: true });
            }
            stack.pop();
            add("Return to the caller", `F(${k}) returns ${cache[k]}; pop the current call.`, snapshot());
            return cache[k]!;
        };
        result = fib(n);
        add("Memoized computation complete", `F(${n})=${result}; every non-base state is computed once. Cache and recursion stack both use O(n).`, snapshot());
    }
    else if (id === "coin-change") {
        const n = numbers(raw, 1, 1, 24)[0];
        if (n < 2)
            throw new Error("Enter at least 2.");
        source = [`Target amount=${n}`, "Coins: 1, 3, 4 (unlimited)"];
        const d = Array(n + 1).fill(Infinity);
        d[0] = 0;
        add("Set base cases", "dp[0]=0; other amounts initially unreachable. Denominations: 1, 3, 4.", {
            values: d.map((x) => (Number.isFinite(x) ? x : 0)),
            labels: d.map((x) => (Number.isFinite(x) ? String(x) : "∞")),
        });
        for (let i = 1; i <= n; i++) {
            for (const coin of [1, 3, 4])
                if (i >= coin)
                    d[i] = Math.min(d[i], d[i - coin] + 1);
            add("Reuse a solved subproblem", `dp[${i}] = ${d[i]}; best result after trying final coins 1, 3 and 4.`, {
                values: d.map((x) => (Number.isFinite(x) ? x : 0)),
                labels: d.map((x) => (Number.isFinite(x) ? String(x) : "∞")),
                active: [i],
                settled: range(i),
                stats: { "States": i },
            });
        }
        result = d[n];
    }
    else {
        const a = numbers(raw);
        add("Input sequence", a.join(", "), { values: a });
        if (id === "prefix-sum") {
            const prefix = [0];
            for (let i = 0; i < a.length; i++) {
                prefix.push(prefix[i] + a[i]);
                add("Accumulate one element", `prefix[${i + 1}] = ${prefix[i]} + ${a[i]} = ${prefix[i + 1]}。`, { values: prefix, active: [i + 1] });
            }
            const l = 1, r = a.length - 1;
            add("Answer with two prefixes", `sum[${l},${r}] = prefix[${r + 1}] − prefix[${l}] = ${prefix[r + 1] - prefix[l]}。`, { values: prefix, active: [l, r + 1] });
            result = prefix;
        }
        else if (id === "two-pointers") {
            a.sort((a, b) => a - b);
            const target = a[0] + a.at(-1)!;
            let l = 0, r = a.length - 1;
            const pairs: number[][] = [];
            add("Sort and set the target", `Target sum ${target} (minimum + maximum); find distinct value pairs. Sorting cost is separate.`, { values: a });
            while (l < r) {
                const sum = a[l] + a[r];
                add("Compare the endpoint sum", `${a[l]} + ${a[r]} = ${sum}; target ${target}.`, {
                    values: a,
                    active: [l, r],
                });
                if (sum === target) {
                    pairs.push([a[l], a[r]]);
                    const x = a[l], y = a[r];
                    while (l < r && a[l] === x)
                        l++;
                    while (l < r && a[r] === y)
                        r--;
                }
                else if (sum < target)
                    l++;
                else
                    r--;
            }
            result = pairs;
            add("All candidates processed", `Value pairs: ${pairs.map((p) => p.join("+")).join("；")}.`, { values: a });
        }
        else if (id === "sliding-window") {
            const k = Math.min(3, a.length);
            let sum = 0, best = -Infinity;
            for (let i = 0; i < a.length; i++) {
                sum += a[i];
                if (i >= k)
                    sum -= a[i - k];
                if (i >= k - 1)
                    best = Math.max(best, sum);
                add(`Move a length-${k} window`, `Add ${a[i]}${i >= k ? `, remove ${a[i - k]}` : ""}; current sum ${sum}.`, {
                    values: a,
                    active: range(Math.min(i + 1, k)).map((j) => i - j),
                    stats: {
                        "Window sum": sum,
                        "Best complete window": Number.isFinite(best) ? best : "Not yet formed",
                    },
                });
            }
            result = best;
        }
        else if (id === "monotonic-stack") {
            const stack: number[] = [], next = Array(a.length).fill(-1);
            for (let i = 0; i < a.length; i++) {
                while (stack.length && a[stack.at(-1)!] < a[i]) {
                    const j = stack.pop()!;
                    next[j] = a[i];
                    add("Pop and resolve an answer", `The next greater value for ${a[j]} is ${a[i]}.`, {
                        values: a,
                        active: [j, i],
                        stats: { "Stack": stack.map((k) => a[k]).join(", ") || "∅" },
                        worklists: [
                            {
                                name: "Monotonic stack \u00B7 top at left (index:value)",
                                items: [...stack].reverse().map((k) => `${k}:${a[k]}`),
                            },
                        ],
                    });
                }
                stack.push(i);
                add("Maintain a decreasing stack", `Push ${a[i]}, awaiting a later greater element.`, {
                    values: a,
                    active: stack,
                    worklists: [
                        {
                            name: "Monotonic stack \u00B7 top at left (index:value)",
                            items: [...stack].reverse().map((k) => `${k}:${a[k]}`),
                        },
                    ],
                });
            }
            result = next;
            add("Output next greater values", "\u22121 means no greater value exists to the right.", {
                values: next,
                labels: next.map(String),
                worklists: [
                    {
                        name: "Unresolved indices \u00B7 no greater values remain to the right",
                        items: [...stack].reverse().map((k) => `${k}:${a[k]}`),
                    },
                ],
            });
        }
        else if (id === "lis") {
            const d = Array(a.length).fill(1);
            for (let i = 0; i < a.length; i++) {
                for (let j = 0; j < i; j++)
                    if (a[j] < a[i]) {
                        d[i] = Math.max(d[i], d[j] + 1);
                        add("Try a smaller predecessor", `a[${j}]=${a[j]} < ${a[i]}，dp[${i}] = ${d[i]}。`, { values: a, active: [i, j], stats: { "Longest at current position": d[i] } });
                    }
                add("Settle this position's answer", `The longest increasing subsequence ending at ${a[i]} has length ${d[i]}.`, {
                    values: d,
                    active: [i],
                });
            }
            result = Math.max(...d);
            add("Take the global maximum", `Longest strictly increasing subsequence length = ${result}.`, {
                values: d,
            });
        }
        else
            throw new Error(`Unknown strategy ${id}`);
    }
    return {
        frames,
        kind,
        result,
        source,
        caption: "DP values come from actual state transitions. Complexity excludes frame copies retained for replay.",
    };
}

strings:
import { recorder, range, textPair } from "./model";
import type { Node, Edge, Trace, Frame } from "./model";
export function strings(id: string, raw: string): Trace {
    const { frames, add } = recorder();
    let result: unknown, kind: Trace["kind"] = "cells";
    let source: Trace["source"], output: Trace["output"];
    if (id === "suffix-array") {
        if (!/^[a-zA-Z]{1,12}$/.test(raw))
            throw new Error("Enter 1\u201312 English letters.");
        const suffixes = range(raw.length).map((i) => ({
            index: i,
            text: raw.slice(i),
        }));
        add("Generate all suffixes", "Each position defines a suffix extending to the end.", {
            matrix: suffixes.map((s) => [s.index, s.text]),
            colLabels: ["Start index", "Suffix"],
        });
        for (let i = 1; i < suffixes.length; i++) {
            const item = suffixes[i];
            let j = i;
            while (j > 0 && suffixes[j - 1].text > item.text) {
                suffixes[j] = suffixes[j - 1];
                j--;
            }
            suffixes[j] = item;
            add("Insert a suffix in lexicographic order", `Insert ${item.text} at position ${j}. This lab uses direct insertion sort, with O(n\u00B3) worst-case character comparisons.`, {
                matrix: suffixes.map((s) => [s.index, s.text]),
                colLabels: ["Start index", "Suffix"],
                cells: [[j, 1]],
            });
        }
        result = suffixes.map((s) => s.index);
        kind = "matrix";
    }
    else if (id === "huffman") {
        if (!/^[a-zA-Z]{1,20}$/.test(raw))
            throw new Error("Enter 1\u201320 English letters.");
        type H = {
            id: string;
            freq: number;
            char?: string;
            left?: H;
            right?: H;
        };
        const freq = new Map<string, number>();
        for (const ch of raw)
            freq.set(ch, (freq.get(ch) || 0) + 1);
        const forest: H[] = [...freq].map(([char, freq], i) => ({
            id: `s${i}`,
            char,
            freq,
        }));
        let seq = 0;
        const codes: Record<string, string> = {};
        let pathIds: string[] = [], encoded = "", decoded = "";
        source = [`Original: ${raw}`, ...[...freq].map(([c, f]) => `${c} × ${f}`)];
        const picture = () => {
            const nodes: Node[] = [], edges: Edge[] = [];
            const go = (p: H, l: number, r: number, depth: number) => {
                nodes.push({
                    id: p.id,
                    label: `${p.char || "Σ"}:${p.freq}`,
                    x: (l + r) / 2,
                    y: 25 + depth * 55,
                    color: pathIds.includes(p.id) ? "orange" : undefined,
                });
                if (p.left) {
                    edges.push({
                        from: p.id,
                        to: p.left.id,
                        label: "0",
                        active: pathIds.includes(p.id) && pathIds.includes(p.left.id),
                    });
                    go(p.left, l, (l + r) / 2, depth + 1);
                }
                if (p.right) {
                    edges.push({
                        from: p.id,
                        to: p.right.id,
                        label: "1",
                        active: pathIds.includes(p.id) && pathIds.includes(p.right.id),
                    });
                    go(p.right, (l + r) / 2, r, depth + 1);
                }
            };
            forest.forEach((p, i) => go(p, (i * 680) / forest.length, ((i + 1) * 680) / forest.length, 0));
            return { nodes, edges };
        };
        const emitH = (title: string, detail: string, extra: Partial<Frame> = {}) => add(title, detail, {
            ...picture(),
            worklists: [
                {
                    name: "Candidate forest \u00B7 linear minimum selection (ascending weight)",
                    items: forest
                        .slice()
                        .sort((a, b) => a.freq - b.freq)
                        .map((p) => `${p.char || p.id}:${p.freq}`),
                },
            ],
            tables: [
                {
                    title: "Codebook under construction",
                    columns: ["Character", "Frequency", "Encoding"],
                    rows: [...freq].map(([ch, count]) => [
                        ch,
                        count,
                        codes[ch] ?? "Pending",
                    ]),
                },
            ],
            stats: {
                "Character count": raw.length,
                "Distinct characters": freq.size,
                "Generated codewords": Object.keys(codes).length,
                "Encoded bits": encoded.length,
            },
            ...extra,
        });
        emitH("Count character frequencies", "Original text and frequencies stay visible. Each symbol starts as a weighted leaf tree.");
        const takeMin = () => {
            let m = 0;
            for (let i = 1; i < forest.length; i++)
                if (forest[i].freq < forest[m].freq)
                    m = i;
            return forest.splice(m, 1)[0];
        };
        while (forest.length > 1) {
            const candidates = forest.slice().sort((a, b) => a.freq - b.freq);
            emitH("Choose the next candidate pair", `Next merge: ${candidates[0].char || candidates[0].id}:${candidates[0].freq} and ${candidates[1].char || candidates[1].id}:${candidates[1].freq}.`, {
                ...picture(),
                checkpoint: true,
                inputState: {
                    source,
                    current: candidates
                        .slice(0, 2)
                        .map((p) => `${p.char || p.id}:${p.freq}`)
                        .join(" + "),
                    pending: candidates
                        .slice(2)
                        .map((p) => `${p.char || p.id}:${p.freq}`),
                    processed: seq,
                    label: "Candidate forest; highlighted pair are this round's smallest trees",
                },
            });
            const left = takeMin(), right = takeMin();
            forest.push({
                id: `n${seq++}`,
                freq: left.freq + right.freq,
                left,
                right,
            });
            emitH("Merge the two smallest trees", `${left.freq} + ${right.freq} = ${left.freq + right.freq}; teaching implementation selects minima linearly without a priority queue.`);
        }
        const walk = (p: H, s: string, ancestors: string[]) => {
            pathIds = [...ancestors, p.id];
            if (p.char) {
                codes[p.char] = s || "0";
                emitH("Reach a leaf and record its code", `${p.char}'s path code is ${codes[p.char]}. ${s ? "Left is 0, right is 1. Only leaves represent symbols, so no code is a prefix of another." : "For a single symbol, use code 0 to preserve repetition count."}`, { checkpoint: true });
            }
            else
                emitH("Generate prefixes along the tree", `Current path ${s || "Root (empty prefix)"}. Visit left appending 0, then right appending 1.`);
            if (p.left)
                walk(p.left, s + "0", [...ancestors, p.id]);
            if (p.right)
                walk(p.right, s + "1", [...ancestors, p.id]);
        };
        walk(forest[0], "", []);
        pathIds = [];
        for (let i = 0; i < raw.length; i++) {
            encoded += codes[raw[i]];
            emitH("Encode the original character by character", `${raw[i]} \u2192 ${codes[raw[i]]}; accumulated bits: ${encoded}`, {
                inputState: {
                    source,
                    current: `${i}: ${raw[i]}`,
                    pending: [...raw.slice(i + 1)],
                    processed: i + 1,
                    label: "Encode the original left to right",
                },
                worklists: [{ name: "Generated bit string", items: [encoded] }],
            });
        }
        let node = forest[0], bitPath = [node.id];
        for (let i = 0; i < encoded.length; i++) {
            if (!forest[0].char) {
                node = encoded[i] === "0" ? node.left! : node.right!;
                bitPath.push(node.id);
            }
            pathIds = bitPath;
            const char = node.char;
            if (char)
                decoded += char;
            emitH(char ? "Reach a leaf and output a character" : "Read one bit and follow an edge", `Bit ${i + 1}: ${encoded[i]}; ${char ? `Output ${char}, then return to the root. Decoded: ${decoded}` : "Not at a leaf yet; read the next bit."}`, {
                worklists: [
                    {
                        name: "Bits awaiting decoding (next bit at left)",
                        items: [encoded.slice(i + 1) || "All bits read"],
                    },
                    { name: "Recovered original text", items: [decoded || "No output yet"] },
                ],
            });
            if (char) {
                node = forest[0];
                bitPath = [node.id];
            }
        }
        pathIds = [];
        result = codes;
        output = {
            title: "Huffman encoding and decoding results",
            columns: ["Character", "Frequency", "Codeword"],
            rows: [...freq].map(([c, f]) => [c, f, codes[c]]),
            summary: [
                `Original: ${raw}`,
                `Encoded bits: ${encoded}`,
                `Decoded text: ${decoded}`,
                `Round-trip check: ${decoded === raw ? "Match" : "Failed"}`,
                `Encoded length ${encoded.length} bits, versus ${raw.length * 8} bits at 8 ASCII bits per character. Excludes codebook, length metadata and container overhead; not an actual file compression ratio.`,
            ],
        };
        emitH("Encoding and decoding complete", `Output shows the codebook, ${encoded.length}-bit encoding and recovered text. Round-trip check: ${decoded === raw ? "Match" : "Failed"}.`, { checkpoint: true });
        kind = "graph";
    }
    else {
        const [text, pattern] = textPair(raw), n = text.length, m = pattern.length, found: number[] = [];
        let comparisons = 0;
        const emit = (title: string, detail: string, offset: number, j = -1) => {
            const width = Math.max(n, offset + m);
            add(title, detail, {
                matrix: [
                    range(width).map((i) => text[i] || "·"),
                    range(width).map((i) => i >= offset && i < offset + m ? pattern[i - offset] : "·"),
                ],
                rowLabels: ["Text", "Pattern"],
                cells: j >= 0
                    ? [
                        [0, offset + j],
                        [1, offset + j],
                    ]
                    : [],
                stats: { "Character comparisons": comparisons, "Matched": found.length },
            });
        };
        emit("Prepare text and pattern", `Text length ${n}, pattern length ${m}.`, 0);
        if (id === "naive-match") {
            for (let i = 0; i <= n - m; i++) {
                let j = 0;
                for (; j < m; j++) {
                    comparisons++;
                    emit("Compare characters", `${text[i + j]} and ${pattern[j]} are ${text[i + j] === pattern[j] ? "equal" : "different"}.`, i, j);
                    if (text[i + j] !== pattern[j])
                        break;
                }
                if (j === m) {
                    found.push(i);
                    emit("Found a full match", `Start ${i}.`, i);
                }
            }
        }
        else if (id === "kmp") {
            const pi = Array(m).fill(0);
            for (let i = 1; i < m; i++) {
                let j = pi[i - 1];
                while (j > 0 && pattern[i] !== pattern[j])
                    j = pi[j - 1];
                if (pattern[i] === pattern[j])
                    j++;
                pi[i] = j;
                add("Build the prefix function", `pi[${i}]=${j}: length of the longest equal proper prefix and suffix.`, {
                    values: pi,
                    labels: [...pattern].map((c, i) => `${c}:${pi[i]}`),
                    active: [i],
                });
            }
            let j = 0;
            for (let i = 0; i < n; i++) {
                while (j > 0 && text[i] !== pattern[j]) {
                    comparisons++;
                    emit("Mismatch: reuse the border", `j falls from ${j} to pi[${j - 1}]=${pi[j - 1]}; text pointer i=${i} does not retreat.`, i - j, j);
                    j = pi[j - 1];
                }
                comparisons++;
                emit("Continue matching", `i=${i}，j=${j}。`, i - j, j);
                if (text[i] === pattern[j])
                    j++;
                if (j === m) {
                    found.push(i - m + 1);
                    emit("Found a full match", `Start ${i - m + 1}; continue looking for overlapping matches.`, i - m + 1);
                    j = pi[j - 1];
                }
            }
        }
        else if (id === "rabin-karp") {
            const mod = 101, base = 31;
            let hp = 0, ht = 0, power = 1;
            for (let i = 0; i < m; i++) {
                hp = (hp * base + pattern.charCodeAt(i)) % mod;
                ht = (ht * base + (text.charCodeAt(i) || 0)) % mod;
                if (i < m - 1)
                    power = (power * base) % mod;
            }
            for (let i = 0; i <= n - m; i++) {
                emit("Compare window hashes", `Window hash=${ht}, pattern hash=${hp}; modulus ${mod}.`, i);
                if (ht === hp) {
                    let equal = true;
                    for (let j = 0; j < m; j++) {
                        comparisons++;
                        if (text[i + j] !== pattern[j]) {
                            equal = false;
                            break;
                        }
                    }
                    if (equal) {
                        found.push(i);
                        emit("Verification succeeded", `Verified characters after a hash match; start ${i}.`, i);
                    }
                    else
                        emit("Hash collision", "Equal fingerprints but different contents: reject the candidate.", i);
                }
                if (i < n - m)
                    ht =
                        ((((ht - text.charCodeAt(i) * power) % mod) + mod) * base +
                            text.charCodeAt(i + m)) %
                            mod;
            }
        }
        else if (id === "z-function") {
            const s = pattern + "#" + text, z = Array(s.length).fill(0);
            let l = 0, r = 0;
            for (let i = 1; i < s.length; i++) {
                if (i <= r)
                    z[i] = Math.min(r - i + 1, z[i - l]);
                while (i + z[i] < s.length) {
                    comparisons++;
                    if (s[z[i]] !== s[i + z[i]])
                        break;
                    z[i]++;
                }
                if (i + z[i] - 1 > r) {
                    l = i;
                    r = i + z[i] - 1;
                }
                add("Reuse the Z interval", `i=${i}, z=${z[i]}, rightmost matching interval [${l},${r}].`, {
                    values: z,
                    labels: [...s].map((c, j) => `${c}:${z[j]}`),
                    active: [i],
                    stats: { "Character comparisons": comparisons },
                });
                if (i > m && z[i] >= m)
                    found.push(i - m - 1);
            }
        }
        else
            throw new Error(`Unknown string lab ${id}`);
        emit("Search finished", found.length ? `All matching starts: ${found.join(", ")}.` : "No matching starts.", found[0] ?? 0);
        result = found;
        kind = "matrix";
    }
    return {
        frames,
        kind,
        result,
        source,
        output,
        caption: "Character indices are zero-based. Inputs are limited to English letters to avoid confusing bytes, code points and graphemes.",
    };
}

math:
import { numbers, range, recorder } from "./model";
import type { Trace, Frame } from "./model";
export function math(id: string, raw: string): Trace {
    const { frames, add } = recorder();
    let result: unknown, kind: Trace["kind"] = "cells";
    if (id === "gcd") {
        let [a, b] = numbers(raw, 2, 2, 999);
        if (!a || !b)
            throw new Error("Both numbers must be greater than 0.");
        add("Start Euclid's algorithm", `Compute gcd(${a},${b}).`, { values: [a, b] });
        while (b) {
            const r = a % b;
            add("Quotient and remainder", `${a} = ${Math.floor(a / b)} \u00D7 ${b} + ${r}; replace with (${b},${r}).`, { values: [a, b, r], labels: ["a", "b", "Remainder"], active: [2] });
            [a, b] = [b, r];
        }
        result = a;
        add("Remainder is zero", `Greatest common divisor = ${a}.`, { values: [a], settled: [0] });
    }
    else if (id === "fast-power") {
        let [b, e] = numbers(raw, 2, 2, 99);
        if (b < 1 || e < 1 || e > 30)
            throw new Error("Base 1\u201399, exponent 1\u201330.");
        const mod = 1009;
        let answer = 1;
        add("Initial state", `Compute ${b}^${e} mod ${mod}.`, {
            values: [answer, b, e],
            labels: ["Result", "Base", "Exponential"],
        });
        while (e) {
            if (e % 2) {
                answer = (answer * b) % mod;
                add("Least significant bit is 1", `Multiply result by the current base modulo ${mod}, obtaining ${answer}.`, {
                    values: [answer, b, e],
                    labels: ["Result", "Base", "Exponential"],
                    active: [0],
                });
            }
            b = (b * b) % mod;
            e = Math.floor(e / 2);
            add("Square and shift right", `Squared base modulo m is ${b}; halved exponent is ${e}.`, {
                values: [answer, b, e],
                labels: ["Result", "Base", "Exponential"],
                active: [1, 2],
            });
        }
        result = answer;
    }
    else if (id === "sieve") {
        const n = numbers(raw, 1, 1, 60)[0];
        if (n < 4)
            throw new Error("The limit must be 4\u201360.");
        const prime = Array(n + 1).fill(true);
        prime[0] = prime[1] = false;
        add("Candidate integers", "0 and 1 are not prime.", {
            values: range(n + 1),
            settled: [0, 1],
        });
        for (let p = 2; p * p <= n; p++)
            if (prime[p]) {
                for (let x = p * p; x <= n; x += p) {
                    prime[x] = false;
                    add("Sieve out composites", `${x} is a multiple of ${p}; start at p\u00B2=${p * p}.`, {
                        values: range(n + 1),
                        active: [x],
                        pivot: p,
                        settled: range(n + 1).filter((i) => !prime[i]),
                    });
                }
            }
        result = range(n + 1).filter((i) => prime[i]);
        add("Remaining values are prime", `Primes: ${(result as number[]).join(", ")}. Gray cells have been eliminated.`, {
            values: range(n + 1),
            active: result as number[],
            settled: range(n + 1).filter((i) => !prime[i]),
        });
    }
    else if (id === "bitmask") {
        const a = numbers(raw, 2, 6);
        const subsets: number[][] = [];
        for (let mask = 0; mask < 2 ** a.length; mask++) {
            const chosen = range(a.length).filter((i) => mask & (1 << i));
            subsets.push(chosen.map((i) => a[i]));
            add("Binary selection switches", `mask=${mask} (${mask.toString(2).padStart(a.length, "0")}), subset {${chosen.map((i) => a[i]).join(", ")}}.`, {
                values: a,
                active: chosen,
                stats: { "Enumerated": mask + 1, "Total": 2 ** a.length },
            });
        }
        result = subsets;
    }
    else if (id === "convex-hull") {
        type P = [
            number,
            number
        ];
        const p: P[] = raw === "1"
            ? [
                [1, 1],
                [2, 2],
                [3, 3],
                [4, 4],
                [1, 4],
                [4, 1],
                [2, 3],
            ]
            : [
                [1, 1],
                [2, 3],
                [3, 2],
                [4, 5],
                [5, 1],
                [6, 4],
                [3, 4],
                [2, 1],
            ];
        p.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        const cross = (a: P, b: P, c: P) => (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
        const key = (a: P) => a.join(",");
        let inputState: Frame["inputState"];
        const emit = (title: string, detail: string, chain: P[]) => add(title, detail, {
            inputState,
            nodes: p.map((a) => ({
                id: key(a),
                label: `(${a.join(",")})`,
                x: 30 + a[0] * 90,
                y: 320 - a[1] * 52,
                color: chain.includes(a) ? "mint" : undefined,
            })),
            edges: chain
                .slice(1)
                .map((a, i) => ({ from: key(chain[i]), to: key(a), active: true })),
        });
        const lower: P[] = [], upper: P[] = [];
        for (const [name, points, chain] of [
            ["Lower chain", p, lower],
            ["Upper chain", [...p].reverse(), upper],
        ] as const)
            for (const [i, pt] of points.entries()) {
                inputState = {
                    source: p.map(key),
                    current: key(pt),
                    pending: points.slice(i + 1).map(key),
                    processed: i,
                    label: name + "Scan order",
                };
                while (chain.length >= 2 &&
                    cross(chain.at(-2)!, chain.at(-1)!, pt) <= 0) {
                    const value = cross(chain.at(-2)!, chain.at(-1)!, pt);
                    const removed = chain.pop()!;
                    emit("Remove a non-left turn", `${name}: remove (${removed}); cross product with candidate (${pt}) is ${value}\u22640.`, chain);
                }
                chain.push(pt);
                emit("Add a boundary candidate", `${name}: add (${pt}).`, chain);
            }
        inputState = {
            source: p.map(key),
            pending: [],
            processed: p.length,
            label: "Upper and lower chains complete",
        };
        const hull = [...lower.slice(0, -1), ...upper.slice(0, -1)];
        emit("Close the convex hull", "All interior points lie inside the boundary; intermediate collinear points are removed.", [
            ...hull,
            hull[0],
        ]);
        result = hull;
        kind = "graph";
    }
    else
        throw new Error(`Unknown mathematics lab ${id}`);
    return {
        frames,
        kind,
        result,
        caption: "Small integers/fixed coordinates make exact states observable. Advanced notes discuss big-integer and floating-point engineering separately.",
    };
}
